INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199230089', 'Tênis Olympikus Wellness 2 Masculino - Grafite', 'O Novo Olympikus Wellness 2 é o tênis ideal para quem busca conforto, amortecimento e estilo no seu dia a dia. O seu solado possui a tecnologia de amortecimento Eleva+ que explora o limite de expansão do EVA, extremamente leve, proporcionando máxima resposta, mantendo conforto e durabilidade. Já o cabedal é feito em tecido poliester dublado com espuma, com textura trazendo um visual clean. Possui ainda logo em relevo, puxador em fita no traseiro para auxiliar no calce e forro de poliéster com espuma. Sua palmilha é anatômica, composta por tecido poliester e EVA, com aplicação gráfica. A TECNOLOGIA: ELEVA + - Tecnologia exclusiva Olympikus, que explora o limite de expansão do EVA para alcançar máxima resposta, proporcionando o efeito trampolim, ou seja, absorvendo o impacto da passada e transformando essa energia em impulsão. Este EVA é leve e de baixa densidade, garantindo menor deformação e mantendo o conforto e a durabilidade.', 309.99, 249.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rcc2-lte6r0yon06jed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F19199230089', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
