INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997667661', 'Sensor TPS CELTA 1.0 1.4 2001/2007 MTE7231 3PINOS - 22359 - 7231', 'Sensor TPS CELTA 1.0 1.4 2001/2007 MTE7231 3PINOS MOTOR 1.0/1.4 MPFI GAS. (GIRO HORARIO) O Sensor de Posição da Borboleta (Throttle Position Sensor – TPS) é utilizado para monitorar a posição do acelerador em um motor de combustão interna. O sensor tem como finalidade informar a posição da borboleta do acelerador. Através do TPS, a UCE obtém informações instantâneas da posição da borboleta permitindo à central identificar a potência que o condutor está requerendo. Essas informações são utilizadas no auxílio do cálculo do tempo de injeção, avanço da ignição,etc...', 120.29, 120.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd4o-lui06eq9sjazdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21997667661', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893512415', 'NINA A VACA', 'NINA A VACA Com uma linguagem poética e lúdica, os livros destinam se a crianças em fase de alfabetização. A coleção é ilustrada por vários ilustradores. Em cada volume é utilizada uma técnica diferente de ilustração, exprimindo a riqueza dos sentidos dos textos. Todos em letra maiúscula (caixa alta).. Informações Adicionais Autor: PEREIRA, EDIMILSON DE ALMEIDA Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: NINA A VACA Idioma: PORTUGUES Páginas: 12 Edição: 1 ISBN-13: 9788588600119 ISBN-10: 8588600110', 19.88, 19.88, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbkm-lpic0vtjj185c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22893512415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993867497', 'MANUAL DO MUNDO 50 EXPERIMENTOS PARA FAZER EM CASA', 'MANUAL DO MUNDO 50 EXPERIMENTOS PARA FAZER EM CASA Esta é uma edição atualizada e em novo formato do primeiro livro do MANUAL DO MUNDO, que já vendeu mais de 80.000 exemplares.Diversão e aprendizado podem se dar muito bem. A prova disso é o MANUAL DO MUNDO, o maior canal de Ciência e Tecnologia em Língua Portuguesa.Ao longo de 12 anos, Iberê Thenório e Mariana Fulfaro publicaram mais de 1.600 vídeos no YouTube e conquistaram mais de 15 milhões de inscritos. Quer aprender a fazer um arco íris dentro de um copo? Congelar água em um segundo? Construir um kart movido a furadeira? Um submarino? Conhecer uma usina nuclear? Bater recordes mundiais? Tem tudo no Manual do Mundo.Neste livro, escrito em parceria com o químico Alfredo Luis Mateus, foram selecionados os experimentos científicos mais divertidos e, ao mesmo tempo, simples de se fazer em casa – muitos deles ainda inéditos no canal.Cabo de guerra sem corda. Foguete movido a água. Projetor feito com celular. Você vai se divertir construindo geringonças e objetos úteis com materiais que tem em casa e que poderiam acabar indo para o lixo.Também vai aprender a fazer jogos, mágicas e arte. Tudo com instruções passo a passo e muitas fotos explicando direitinho como se faz. Além disso, encontrará explicações científicas fáceis de entender sobre o que acontece em cada experimento.. Informações Adicionais Autor: ALFREDO LUIS; THENÓRIO, IBERÊ Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: MANUAL DO MUNDO 50 EXPERIMENTOS PARA FAZER EM CASA Idioma: INDEFINIDO Páginas: 192 Edição: 2 ISBN-13: 9786555640793 ISBN-10: 6555640790', 89.9, 89.9, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbky-lq3dvaktev4794', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22993867497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
