INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693041968', 'Colônia Granado Bebê Tradicional 100ml', 'Características Principais do Produto: Marca:Granado Modelo:Bebê Segmento:Colônia Informações Adicionais do Produto: Sua fórmula suave tem base aquosa (não contém álcool) e foi especialmente desenvolvida para refrescar e perfumar a delicada pele do bebê. Indicada para todas as faixas etárias, inclusive recém-nascidos. Dermatologicamente testada. Embalagem com válvula em spray. Livre de corantes, parabenos, álcool etílico e ingredientes de origem animal. Modo de Uso: Aplique primeiramente nas mãos e espalhe sobre a pele do bebê. Composição: aqua (water), peg-40 hydrogenated castor oil, parfum (fragrance), benzyl alcohol, polysorbate 20, peg-12 dimethicone, ethylhexylglycerin, sodium gluconate, peg-12 allyl ether, peg-12, tocopherol, cinnamyl alcohol, citronellol, coumarin, geraniol, hexyl cinnamal, limonene. Conteúdo: 100ml. Fornecedor:Granado', 84.1, 65.9, NULL, 'Mom & Baby > Bath & Body Care > Baby Colognes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-824hg-mpiaepoyjx1q11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23693041968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
