INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798829553', 'Óleo em Creme DaBelle Fortalecedor SOS Crescimento 190ml', 'Características do Produto Marca: DaBelle Volume: 190ml Linha: SOS Crescimento Especificações Gerais do Produto: Com Multivitaminas, Óleo de Rícino, D-Pantenol e Biotina Necessidade: Crescimento, Uso Diário Tipo de Cabelo: Normais e Todos os Tipos Tratamento multifuncional essencial para cabelos fragilizados e quebradiços Fórmula cremosa Rica em nutrientes que fortalecem os fios para prevenir a queda devido à quebra 0% parabenos, corantes, óleo mineral e sal Multifuncional: Fortalecedor noturno Pré-shampoo Umectação Filtro UV Proteção térmica Leave In Mode de usar: Fortalecedor noturno: Aplique do comprimento às pontas antes de dormir. O enxágue ao acordar é opcional. Pré-shampoo: Nos cabelos úmidos, aplique do comprimento às pontas. Deixe agir por 5 minutos. Enxágue e prossiga com sua rotina de higienização e tratamento. Umectação: Enluve os cabelos ainda secos mecha por mecha. Deixe agir por pelo menos 30 minutos e siga sua rotina de tratamento. LEAVE IN: Nos cabelos úmidos, distribuir uniformemente para facilitar o desembaraço e a finalização. Protetor térmico: Possui proteção térmica e facilita a escovação. Aplique antes de fazer escova e ao usar ferramentas de calor como secador, difusor e chapinha. Filtro UV: Aplique antes de expor os cabelos ao sol, praia, piscina e reaplique quando mergulhar ou sempre que achar necessário. Fornecedor: DaBelle', 29.51, 29.51, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-824i8-mpiayhp538qp45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F22798829553', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
