INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16486190129', 'Coturno Feminino Falcucci Bota Plataforma Tratorado Cano Curto Confort em Promoção', 'Temos o produto em estoque para envio imediato, tudo isso para que você receba sua bota o mais rápido possível. Fique atenta: Nossas botas são realmente costuradas (Blaqueadas), não é apenas uma costura "disfarçada", é uma costura real para maior durabilidade e resistência do seu calçado. Essa costura serve, além do aspecto visual, também para assegurar que a sola nunca irá se descolar do calçado. Nossas botas têm forma padrão, ou seja, você pode comprar o número que costuma usar normalmente. Mas, para efeito de confirmação, temos abaixo uma tabela com as medidas das PALMILHAS das botas para que, em caso de dúvidas, você possa medir uma palmilha sua e comparar com a tabela. MEDIDA DAS PALMILHAS: 33 - 22 cm 34 - 23 cm 35/36 - 24 cm 37/38 - 25,5 39/40 - 27 cm (Se medir sua palmilha com uma régua, considerar desde o numero 0 (zero)) ALTURA DO CANO (medida da sola até o cano): 19CM ALTURA DA SOLA: 5CM Material: Verniz ou Napa (Couro Sintético) Solado: Emborrachado macio antiderrapante Tratorado (e realmente costurada) Última moda entre as "Blogueirinhas", esse coturno é simplesmente fantástico! Ele dá uma pegada Fashionista em qualquer look, deixando seu visual mais moderno e despojado. Pode ser usado com calça, shots, saia, vestido.. Pode apostar sem medo de errar. E claro, esse precinho e qualidade você só encontra em nossa loja!', 99.9, 49.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-22090-o4goegzypvhvc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324642050%2F16486190129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29637693419', 'Tênis Infantil Menina Cadarço Onça Antiderrapante Anatômico Prático Moderno Fashion Moda Casual', '👟 Tênis Infantil Kidy RK 70 – Conforto, Estilo e Praticidade O Tênis Kidy RK 70 é ideal para meninas que amam estilo sem abrir mão do conforto. Com design moderno e toque fashion, é anatômico e acompanha o formato dos pezinhos em crescimento. Possui calce fácil, que traz autonomia para a criança e praticidade para os pais. A tecnologia Passos Fortes oferece amortecimento e suporte na pisada, perfeito para o dia a dia das pequenas. ✅ Destaques: Formato anatômico: mais saúde e conforto Calce fácil: prático para vestir Tecnologia Passos Fortes: absorção de impacto Leve, seguro e estiloso 📏 Tabela de Medidas (aproximadas): Tamanho 25 – 16,0 cm Tamanho 26 – 16,5 cm Tamanho 27 – 17,5 cm Tamanho 28 – 17,8 cm Tamanho 29 – 18,8 cm Tamanho 30 – 19,6 cm Tamanho 31 – 20,1 cm Tamanho 32 – 20,8 cm Tamanho 33 – 21,5 cm Tamanho 34 – 22,0 cm 🔍 Sobre este item: Produto: Tênis Infantil Marca: Kidy Modelo: RK 70 Gênero: Menina Fechamento: Calce fácil Cabedal: Sintético Forro: Têxtil Palmilha: EVA Solado: PVC Numeração: do 25 ao 34 Indicado para: Escola, passeios, dia a dia 🧒 Sobre a Kidy: A Kidy é referência em calçados infantis que aliam conforto, saúde e estilo. Cada modelo é pensado para garantir bem-estar e acompanhar o crescimento saudável dos pequenos.', 189.99, 159.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcgmyoe0e43653', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F29637693419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193270816', 'Quadro Decorativo Paisagem Abstrata 2 Telas Moldura Com ou Sem Vidro Sala Quarto Escritorio', 'Quadro Decorativo Abstrato Mármore 2 Telas Sala / Quarto / Escritorio Transforme qualquer ambiente com a elegância e sofisticação do nosso Quadro Decorativo Composição 2 Telas. Disponível em duas dimensões, este conjunto de telas abstratas é perfeito para adicionar um toque de arte contemporânea à sua sala, quarto ou escritório. Quadro Decorativo Composição 2 Telas 90x60cm: Material da Imagem: Papel fotográfico premium. Material da Moldura: Madeira de reflorestamento revestida em preto. Dimensões: 60cm de largura e 90cm de comprimento. Acompanha: Suporte de serrilha Acabamento: Fita kraft. Destaques: Design atemporal, alta qualidade de imagem e moldura, certificado FSC de manejo florestal. Quadro Decorativo Composição 2 Telas 50x75cm: Material da Imagem: Papel fotográfico premium. Material da Moldura: Madeira de reflorestamento revestida em preto. Dimensões: 50cm de largura e 75cm de comprimento. Acompanha: Suporte de serrilha Acabamento: Fita kraft. Destaques: Design atemporal, alta qualidade de imagem e moldura, certificado FSC de manejo florestal.', 210.0, 178.5, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134207-820m0-mpkqsfa2k8w305', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408999524%2F22193270816', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
