INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999556324', 'Quadro Decorativo Abstrato Cidade Com Moldura Com Ou Sem Vidro', 'QUADRO DECORATIVO ABSTRATO CIDADE MOLDURA COM OU SEM VIDRO Este quadro decorativo abstrato captura a essência vibrante e dinâmica de uma cidade moderna. Com uma paleta de cores ousada e contrastante, as formas geométricas e linhas fluidas se entrelaçam para criar uma representação estilizada de arranha-céus, ruas movimentadas e luzes urbanas. As pinceladas expressivas e texturas variadas conferem profundidade e movimento à composição, evocando a energia incessante e a diversidade cultural de uma metrópole. Ideal para adicionar um toque contemporâneo e sofisticado a qualquer ambiente, este quadro é uma celebração visual da vida urbana. Dimensões Disponíveis : Disponível em dois tamanhos versáteis para diferentes ambientes: 50x75 cm , 60x90 Perfeito para dar destaque a paredes menores ou criar composições elegantes em espaços compactos. Ideal para preencher paredes maiores, proporcionando um impacto visual marcante em salas de estar, quartos ou escritórios. Você pode escolher as opções de cor da moldura e também pode optar pelo quadro com ou sem vidro.', 160.0, 136.0, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134207-820ma-mptk9hzyp534f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408999524%2F18999556324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994296275', 'Saleiro Pimenteiro Twist Azul Plasútil', 'Saleiro Pimenteiro Twist Azul Plasútil Dimensao: (Diâmetro x Alt): 5,2x8,8 cm - Fabricado em poliestireno (PS). Um tipo de plástico rígido semelhante ao acrílico. - Aparência cristalizada: brilho do vidro. - Atóxico e livre de bisfenol-A (BPA FREE). - Não pode ser levado ao freezer, micro-ondas e lava-louças. Não lavar com água quente. - Lavar com o lado macio da esponja e sabão neutro..', 12.9, 12.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-820mm-mnmvxblkuy2ob7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F22994296275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398442062', 'Junta do cárter Mitsubishi L300 1986 a 2000 SABÓ 86013', 'Descrição: A Junta do cárter SABÓ 86013 é uma peça que serve nos veículos HYUNDAI H 100, HR / MITSUBISHI L200, L300, PAJERO. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Aplicação: - HYUNDAI H 100 2.5 DIESEL 2.5 L 8V SOHV L4 1994 a 2007; - HYUNDAI HR LONGO CHASSIS ALTO STD GL 2.5 L 8V SOHC L4 2007 a 2012; - HYUNDAI HR LONGO CHASSIS BAIXO STD GL 2.5 L 8V SOHC L4 2007 a 2014; - HYUNDAI HR LONGUE DECK STD 2.5 L 16V DOHC L4 2014 a 2024; - HYUNDAI HR LONGUE DECK STD 2.5 L 8V SOHC L4 2007 a 2011; - MITSUBISHI L200 EVO 2.5 L 8V SOHC L4 2003 a 2003; - MITSUBISHI L200 GC 2.5 L 8V SOHC L4 1997 a 2003; - MITSUBISHI L200 GL 2.5 L 8V SOHC L4 1994 a 2007; - MITSUBISHI L200 GL 4X4 2.5 L 8V SOHC L4 1997 a 2007; - MITSUBISHI L200 GLS 4X4 2.5 L 8V SOHC L4 1997 a 2011; - MITSUBISHI L200 HPE 2.5 L 8V SOHC L4 2004 a 2007; - MITSUBISHI L200 L 200 2.5 L 8V SOHC L4 1994 a 1996; - MITSUBISHI L200 L 2.5 L 8V SOHC L4 1999 a 2003; - MITSUBISHI L200 OUTDOOR 2.5 L 8V SOHC L4 2004 a 2007; - MITSUBISHI L200 R 4X4 2.5 L 8V SOHC L4 1999 a 2007; - MITSUBISHI L200 SPORT 2.5 L 8V SOHC L4 1997 a 2003; - MITSUBISHI L300 2.5 DIESEL VAN 2WD 2.5 L 8V SOHC L4 1986 a 2000; - MITSUBISHI PAJERO GLX 2.5 L 8V SOHC L4 1990 a 2000; - MITSUBISHI PAJERO SPORT HPE 2.5 L 8V SOHC L4 2008 a 2009; Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 58.65, 58.65, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-82628-mkri2b0w9e6af1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343288194%2F23398442062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20339414814', 'Bíblia Anote Ilustrada | NVT Capa Dura Tela Branca | Espiral', 'Com a Bíblia Ilustrada Anote, a leitura da Palavra de Deus se torna uma agradável experiência de fé, beleza e inspiração. Nos espaços laterais de cada página, o leitor contempla lindas ilustrações com base nos textos bíblicos e tem à disposição espaço para registrar suas percepções, orações e anotações – é como ter a experiência de se tornar um autor do texto sagrado. A Bíblia Ilustrada Anote traz a Nova Versão Transformadora (NVT) das Sagradas Escrituras, uma tradução contemporânea que facilita o entendimento e preserva, intocado, o eterno conteúdo inspirado pelo Senhor. Modelo: Tela Branca ISBN: 9786556551289 Código do produto: 114706 Autor: Mundo Cristão Páginas: 1024 Formato: A24 x L17 x P3,5cm Acabamento: Capa dura espiral Peso: 1130g', 147.9, 147.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/50d023a31d9e0d450833904496f159a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F20339414814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097874394', 'Planner Estações | Viviane Martinello | Capa verde | Editora Vida', 'Planner Estações | Viviane Martinello | Capa verde O Planner Estações, by Viviane Martinello, é um produto único no mercado por unir tarefas do cotidiano, cuidado pessoal e familiar, espiritualidade e saúde. Além do tradicional espaço para anotações de todas as suas tarefas, você encontrará guia de autocuidado e autoconhecimento, direcionamento para tempo de qualidade com sua família, espaço para anotação de seu devocional, plano de leitura bíblica e muito mais. Viviane Martinello é casada com o pastor Telmo Martinello, com quem tem duas filhas: Vitória e Isabela. Junto ao seu esposo, pastoreia a Abba Pai Church, na cidade de Criciúma, SC. Com um chamado de Deus para alavancar as mulheres de sua geração, escreveu os livros Mulheres Improváveis e Mulheres Enraizadas. Ela também é idealizadora e mentora do projeto Casa de Isabel, uma plataforma de ensino e acompanhamento on-line que já impactou milhares de cristãs ao redor do mundo. Por meio de seu testemunho de vida, Viviane tem auxiliado diversas pessoas a encontrarem restauração e cura interior em Cristo. Autor: Viviane Martinello Editora: Vida Acabamento: Capa Dura Dimensões: 16 cm largura x 23 cm altura Número de páginas: 224', 76.99, 69.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1en30rh7faa31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F21097874394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19798741972', 'Kit 2 Livros O Despertar da Leoa + Como ter o Coração de Maria no Mundo de Marta', '" Kit O Despertar da Leoa + Como ter o Coração de Maria no Mundo de Marta " O Despertar da Leoa : Uma leoa que se levanta do seu sono representa uma imagem magnífica de força, paixão e beleza. Sua simples presença define a paisagem, protege os seus filhotes e confere poder ao leão. Em grupos, as leoas se tornam uma força criativa e estratégica que não deve ser ignorada, prestes a mudar o mundo que as cerca. VOCÊ TAMBÉM É UMA LEOA. Mulheres, é hora de... DESPERTAR... Deus não salvou vocês para domá-las. DESPERTEM... Para uma vida de paixão feroz. DESPERTEM... Para uma oração perigosa, um poder assombroso e um propósito em conjunto. DESPERTEM... Sua reação pode mudar o seu mundo. Cheio de considerações notáveis sobre a natureza e com uma profundidade enorme de referências bíblicas às leoas, O Despertar da Leoa é um chamado para as mulheres se levantarem com força e número para transformar o mundo. Detalhes do Produto: Autor: Lisa Bevere Editora: Chara Acabamento: Brochura Dimensões: 16 larg. X 23 alt. Número de páginas: 252 Como ter o Coração de Maria no Mundo de Marta : Como fortalecer a nossa comunhão com Deus em uma vida atarefada? A vida da mulher de hoje não é tão diferente da vida de Maria e Marta no Novo Testamento. Através desta história bíblica, a autora demonstra como, nesta época agitada e corrida, podemos nos aproximar do Senhor, pois, com ternura, Ele nos convida para escolhermos a “melhor parte”. Detalhes do Produto: Autor: Joanna Weaver Editora: Cpad Acabamento: Brochura Dimensões: 14 larg. X 21 alt. Número de páginas: 246', 75.99, 75.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qves-ljft484wazgt2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F19798741972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498328080', 'Boneco Funko Pop! Capitão América 4 - Capitão América (Sam)', 'Adicione o herói que simboliza uma nova era à sua coleção com o Boneco Funko Pop! Capitão América. Inspirado no filme da Marvel Studios, este incrível boneco de vinil com cabeça oscilante traz Sam Wilson como o Capitão América, pronto para liderar sua equipe de super-heróis. Com aproximadamente 10 centímetros de altura, é um item essencial para fãs de Marvel e colecionadores. Não perca a chance de completar sua coleção com esse símbolo de coragem e justiça!', 164.99, 99.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-8262b-mlwd9ghnoh73e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F22498328080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694011981', 'Boneco Funko Pop! DC Comics Superman: Legacy - Lex Luthor', 'O maior inimigo do Superman está pronto para causar problemas na sua coleção com o Boneco Funko Pop! Lex Luthor! Com seu visual clássico e pose imponente, Lex Luthor é presença indispensável para fãs da DC Comics. A figura de vinil tem cerca de 10 centímetros de altura e é perfeita para completar sua linha do Homem de Aço!', 164.99, 164.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-mcinx9atrgpa27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F23694011981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22620061729', 'Sensy & Trat Aqua Serum 250ml Spray Hidratante para Cães e Gatos Centagro', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - DESCRIÇÃO: O Aqua Serum Sensy & Trat é indicado para a hidratação profunda dos pelos e peles xeróticas (secas) e sensíveis (atópicas) sem deixá-los oleoses e pesados. - - - - - MODO DE USO: Aplicar na pelagem úmida após o banho preferencial com um shampoo da Linha Sensy & Trat e secar naturalmente ou com auxílio de secador. Pode ser aplicado na pelagem seca para escovação diária e manutenção da hidratação. Ao aplicar nos pelos secos promover prévia escovação no sentido contrário aos pelos, pulverizar e escovar os pelos para distribuir uniformemente sobre a pelagem. Não enxague. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 130.1, 67.26, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-llces1y64r4b11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F22620061729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299194670', 'Tapete Passadeira 1,00 x 0,60 Antiderrapante Corredor Quarto Sala Felpudo Peludo', 'Transforme Seu Lar com Nossas Lindas Passadeiras Felpudas! 🧡👇 🚀 Envio Imediato: Faça seu pedido hoje e ele será enviado em no máximo 24 horas! Com nossa fabricação própria, garantimos não só rapidez, mas também o melhor preço do mercado e qualidade incomparável. 💰 Satisfação Garantida ou Seu Dinheiro de Volta: Nossa confiança na qualidade da nossa passadeira é tamanha que oferecemos total garantia de satisfação ou a devolução do seu dinheiro. Já foram + de 1 milhão de clientes atendidos! 📏 Dimensões Perfeitas para Conforto Máaaximo: As Passadeiras medem 1 metro de comprimento por 60 centímetros de largura, com pêlos de 4 cm de altura, é ideal para qualquer ambiente. Cada fio do tapete é super peludo e macio, oferecendo uma sensação suave ao toque, similar à seda. Você irá pisar nas nuvens!. 😍 Você pode lavar na máquina: Coloque a sua Passadeira na máquina de lavar e pronto... Terá ela tão linda e cheirosa que vai parecer que você acabou de comprar!. 🛡️ Qualidade e Segurança: Nossas Passadeiras são antiderrapantes, antialérgicas, e não sujam facilmente, ideal para quem possui idosos, crianças ou pets em casa. E mais, elas podem ser lavadas na máquina, garantindo praticidade e durabilidade. 🏆 Mais de 1 MILHÃO de Tapetes Vendidos na Internet: Junte-se à vasta gama de clientes satisfeitos que escolheram a nossa loja. Com mais de 1 milhão de Tapetes vendidos, vamos enviar seu pedido com todo Amor e Carinho! 🔁 Clientes Fieis: 97,6% dos nossos clientes retornam para mais compras, comprovando que somos a melhor opção do mercado. 🏠 Impressione Suas Visitas: Deixe suas visitas de queixo caído com a beleza e o aconchego que sua Passadeira trará para sua casa. Ela é ideal pra você ou para presentear quem a gente ama! ⏰ Estoque Limitado - A Hora de Agir é Agora!: Nosso estoque é altamente procurado e pode se esgotar a qualquer momento. Não perca a oportunidade de transformar seu lar com as Passadeiras queridinhas do momento! 🧡', 44.9, 27.9, NULL, 'Home & Living > Decoration > Carpets & Rugs', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mju93te6j9c63c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346235717%2F19299194670', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15309061562', 'A Culpa Não É Sua Livro Mundo Cristão', 'Seu passado não define quem você é! Está cansada, sobrecarregada, desanimada e esgotada? Apesar de ser vítima, as pessoas insistem em culpá-la? A culpa não é sua! Fabiola Melo sabe exatamente como você está se sentindo, pois também já se sentiu assim. Por mais doloroso que possa ser, existe a possibilidade de recomeçar, e por isso a mensagem que ela quer passar a você é: Coragem! Coragem para seguir em frente. Coragem para recomeçar. Coragem para ser livre! Seu passado não define quem você é! Existem outras mulheres como você. Suas histórias entristecem, mas são cheias de esperança. E podem ser histórias com um final feliz! Recebo diariamente muitos pedidos de socorro de garotas aprisionadas por dor, sofrimento e culpa em razão de abusos sofridos. Este livro é uma resposta a elas, uma contribuição para levar pessoas que guardam gritos em seu silêncio a encontrar um chão firme em que pisar. Se você é das que clamam por ajuda junto a uma multidão surda, em razão de abusos sofridos ou que ainda sofra, peço que mantenha a calma e seja forte, pois existe uma luz no fim do túnel. Fabiola MeloNúmero de Páginas 144', 36.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/450311f96eec312f88b51fe1faa99b05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F15309061562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294287307', 'Cabo Som Automotivo Rca 5 Metros + 2 Cabos Y E-tech Carro P/modulo', 'KIT 02 PÇS CABO RCA Y 2 MACHOS 1 FÊMEA + 01 PÇ CABO RCA 5 METROS E-TECH INJETADO BLINDADO FLEXIVEL - Desenvolvida para o melhor custo benefício, com conectores levemente revestidos em Ouro, com tecnologia que diminui interferências na transmissão de áudio ou vídeo e um revestimento em PVC translúcido flexível de fácil torção e instalação com condutor trançado de fios bimetálicos livre de oxigênio (OFHC), recomendado para amplificadores de Baixa Potência. Confira suas principais características: CARACTERÍSTICAS CABO RCA Y 2 MACHOS / 1 FÊMEA - 1 Conector Fêmea - 2 Conectores Machos - Comprimento 30 cm - Alta Performance - Alta Flexibilidade - Conector Blindado CARACTERÍSTICAS CABO RCA 5 METROS - 4 Conectores Machos - Comprimento 5 metros - Alta Flexibilidade - Conector Blindado Conteúdo da Embalagem: • 02 Cabos Rca Y 2 Machos 1 Fêmea Injetado • 01 Cabo Rca 5 Metros Injetado • Garantia de 3 meses. • Imagens Meramente Ilustrativas. • Todos os Nossos Produtos São Novos, Originais e Acompanham Nota Fiscal. • Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 59.9, 33.55, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md0dm8495buaf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1315857028%2F23294287307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258457509', 'Conjunto Moletom Menino Jaqueta E Calça Select Azul', 'Conjunto moletom infantil masculino Select, ideal para conforto e estilo no dia a dia. A jaqueta possui capuz, estampa em silk, punhos nas mangas e fechamento em zíper, garantindo praticidade e proteção nos dias mais frios. A calça conta com cós elástico que proporciona melhor ajuste ao corpo e punhos nas pernas. Um conjunto versátil, confortável e perfeito para acompanhar os meninos em diversas atividades.', 74.99, 54.99, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqi3ydg1umtpc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58258457509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994847947', 'Retrovisor Cruze 2011 2012 2013 2014 2015 2016 Eletrico', '🚘 Retrovisor Externo Chevrolet Cruze 2011 a 2016 – Elétrico (Cinza / 3 Fios) ✨ CARACTERÍSTICAS: Produto Novo: Ótima qualidade e excelente acabamento para manter a segurança, a visibilidade e a estética do seu veículo. Estrutura Robusta: Carcaça fabricada em plástico automotivo de alta densidade, resistente a impactos cotidianos e variações climáticas. Pronto para Uso: Acabamento na cor cinza, oferecendo excelente cobertura e alinhamento visual com as linhas do carro. 🔧 ESPECIFICAÇÕES TÉCNICAS: Regulagem: Elétrica. Conector: Sistema de 3 Fios (responsável pelo ajuste elétrico do espelho). Cor da Capa: Cinza. Componentes: Acompanha espelho (lente) e base de fixação interna. Encaixe Sob Medida: Furações e base desenhadas exatamente para um encaixe firme na porta. 🚗 COMPATÍVEL COM OS MODELOS (Cruze G1 - Sedan e Sport6): Chevrolet Cruze 2011 Chevrolet Cruze 2012 Chevrolet Cruze 2013 Chevrolet Cruze 2014 Chevrolet Cruze 2015 Chevrolet Cruze 2016 (Compatível com as versões LT e LTZ da primeira geração. Não aplicável no Novo Cruze G2 lançado no segundo semestre de 2016). ⚠️ IMPORTANTE: Lado do Produto: Verifique o lado desejado (Motorista / Esquerdo ou Passageiro / Direito) antes de finalizar a sua compra. Funções Extras: Verifique se o seu modelo utiliza a configuração de 3 fios (ajuste elétrico simples). Este modelo não possui pisca integrado na capa ou rebatimento elétrico automático. Instalação Profissional: Deve ser instalado por um profissional especializado para garantir a correta conexão da fiação e evitar danos ao sistema elétrico do veículo; não nos responsabilizamos por instalação mal realizada. 🔧', 576.99, 328.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-820lq-mp1413hqhbt180', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1386895250%2F23994847947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998739496', 'Escorredor de Cozinha Arroz Massa Legumes Multiuso 27cm em Aço Inoxidável', '🥗 Tigela para Lavar Arroz com Peneira – Escorredor Multifuncional em Aço Inox ✅ Praticidade no dia a dia – Ideal para lavar e escorrer arroz, legumes, frutas, grãos, soja e até macarrão. Uma só tigela para várias funções na sua cozinha. ✅ Drenagem Inteligente – O design inclinado com peneira integrada garante escoamento rápido e eficiente da água, proporcionando alimentos bem lavados e livres de excesso de líquido. ✅ Material Premium – Produzida em aço inoxidável de alta qualidade, resistente, durável e com acabamento polido para dar um toque sofisticado à sua cozinha. ✅ Fácil de Limpar e Guardar – Basta enxaguar com água após o uso e pendurar para economizar espaço. Simples, rápido e higiênico. ✅ Uso Versátil – Perfeita para cozinhas domésticas, restaurantes, camping ou qualquer lugar onde praticidade e eficiência são indispensáveis. 📏 Especificações: Material: Aço Inoxidável Diâmetro: 27 cm 📦 Conteúdo da Embalagem: 1 Tigela para Lavar Arroz com Peneira ✨ Mais praticidade e eficiência na sua cozinha! Garanta já a sua Tigela Escorredora Multifuncional em Inox e facilite o preparo das suas receitas favoritas.', 49.9, 29.9, NULL, 'Home & Living > Kitchenware > Strainers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfk3zlcdv11ga9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1407654055%2F22998739496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
