INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44027590118', 'Kit Mochila De Costas Escolar Lilica Ripilica Lovit Vibrant + Lancheira + Estojo - Pacific', 'O Kit Mochila de Costas Escolar Lilica Ripilica Lovit Vibrant com Lancheira e Estojo da Pacific é perfeito para tornar a rotina escolar ainda mais prática e encantadora. Com design colorido e alegre da Lilica Ripilica, o kit oferece mochila espaçosa para livros e cadernos, lancheira ideal para transportar os alimentos com organização e estojo funcional para os materiais escolares. Produzido com materiais resistentes e ótimo acabamento, é a escolha certa para unir estilo, funcionalidade e qualidade em um só conjunto. CARACTERES: Marca: Pacific Tamanho: Único Cor da Mochila: Colorida Dimensão da Mochila: 3cm x 30cm x 46cm (LxCxA) Dimensão da Lancheira: 5cm x 20cm x 27cm (LxCxA) Dimensão do Estojo: 4cm x 11cm x 24cm (LxCxA) Ean Mochila: 7899690515412 Ean Lancheira: 7899690515429 Ean Estojo: 7899690515443 INMETRO: 005024/2016 INMETRO: 005023/2016', 445.99, 419.0, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/br-11134207-81ztc-miq8sueikv0j36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F44027590118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
