INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14913232861', 'Argila escolar massa de modelar Branca Utiguti pote com 500g Licyn', 'Produto certificado no âmbito brasileiro de qualidade, conforme Portaria Inmetro Nº 333/2012: Segurança, Compulsório, Registro 007603/2017, OCP0061, INMETRO Argila escolar massa de modelar Utiguti pote com 500g - Licyn A argilinha é indicada para uso escolar e também para artesanato. Desenvolvida para atividades lúdicas a massa de modelar com argila combina argila mineral purificada e aglutinantes minerais e vegetais. Sua textura, densidade e maleabilidade propiciam o desenvolvimento da coordenação motora e a percepção de formas e texturas variadas por meio da criação de esculturas. Macia e consistente, levemente aromatizada e muito fácil de ser manuseada po crianças e adultos. Depois de seca pode ser lixada e pintada com tintas solúveis em água, a base de esmalte, óleos, vernizes e canetas hidrográficas. Detalhes: - Cor: Branca - Pote de 500 gramas', 27.0, 27.0, NULL, 'Stationery > Art Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7renx-m26mx9rmnyj935', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F14913232861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494885817', 'Tapete Higiênico Tico Pads, 50 Unidades', 'Tapete Higiênico Blue Tico Pads Para Cães 50Un. 60cmX55cm O Tapete Higiênico Blue Tico Pads é ideal para nós que temos cãezinhos, propicio para portes pequenos de cães. Um tapete com super absorção evitando patinhas molhadas, as laterais contem vedação total, impedindo vazamento, com adesivo de alta fixação facilitando o uso e compõem-se de inibidor de odor, além de ser um ótimo auxiliar para a limpeza de nossa casa. Ensinar nossos amiguinhos a fazerem suas necessidades em certos locais, é uma tarefa difícil e o Blue Tico Pads nos assessora nesse desafio contento atrativo canino facilitando muito os cuidados com nossos filhotes. - Indicado para cães de pequenos portes; -Indicado para treinamento de filhotes; -Tapete Higiênico; -Alta Absorção; -Contém 50 tapetes; -Com inibidor de odor; - Atente-se à informações da embalagem; -60cm X 55cm - Embalagem com 50 unidades.', 123.9, 123.9, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/sg-11134201-8260s-mlwbh1q637r963', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F22494885817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
