INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099195699', 'Cortador Pisos e Azulejos Cortag HD-500 G2', 'Características Principais: Marca: Cortag Ean: 7897451431865 Características Adicionais: Capacidade de corte até 10 mm de espessura Pode ser utilizada com cerâmica e porcelanato Indicada para o corte de pisos e revestimentos A linha de Cortadores Manuais HD foi projetada para atender as mais diversas demandas de corte de pisos cerâmicos e porcelanatos Benefícios: Alça para transporte Suporte das guias em alumínio injetado Base em chapa de aço carbono com pintura eletrostática em pó Sistema de separação em alumínio injetado para maior vida útil Barra de encosto em alumínio injetado para maior resistência e durabilidade Limitador lateral garantindo medidas uniformes em cortes retos ou em diagonal Dimensões: Comprimento de Corte: 50 cm Corte Diagonal: 36 cm x 36 cm Espessura de Corte: 10 mm Fornecedor: Cortag Industria E Comercio Ltda', 176.7, 176.7, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gm-mpiaqwylerk28f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23099195699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23304305334', 'Balcão Gabinete de Pia Armário de Cozinha 1 Porta e 2 Gavetas Glamy Madesa', 'O balcão de pia da linha Glamy é o produto ideal para quem procura praticidade e beleza. O design é atual e pensado para se ter o máximo de aproveitamento do espaço interno. Serve para armazenar de forma organizada panelas, louças, talheres e utensílios. Desenvolvido com materiais de alta qualidade como puxadores em alumínio, dobradiças metálicas e Pintura em Poliéster com 7 camadas protetoras que aumentam a resistência e durabilidade do móvel. O espaço para a colocação de tampo ou pia é de 120 cm de largura por 52 cm de profundidade. A linha de cozinhas Glamy é totalmente modulada. É possível combinar este balcão com outros módulos disponíveis na linha. Inclusive combinando diferentes cores, para você criar a cozinha dos seus sonhos. Itens inclusos: - Um (1) balcão de 120 cm de largura com uma (1) porta, duas (2) gavetas e frente fixa. (Não possui tampo.) Código do produto: G2412309GL Obs.: A Madesa não disponibiliza serviço de montagem. O produto segue com manual e todas as ferragens necessárias para a instalação. A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 789.99, 586.95, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rd4h-lx8nkiynvsjw3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F23304305334', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
