INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16710476169', 'Leave-on Refresh Grandha Creme Sem Enxágue para Cabelos Frágeis e Oleosos 120g', 'Descrição: Refresh Grandha Leave-On 120g O Refresh Leave-on traz um blend que harmoniza o sistema capilar, tratando os cabelos frágeis e refrescando o couro cabeludo. Ideal para ser usado em conjunto com o Kit Refresh Flores & Vegetais. Da linha de terapia capilar, Flores e Vegetais, combina um toque de óleo essencial de lavanda com os cuidados da calêndula e a refrescância da hortelã para a harmonização do sistema capilar e o tratamento de cabelos frágeis. Refresh Leave-On 120g Principais Ativos -Calêndula - Hortelã - Lavanda Francesa Óleo Essencial de Lavanda O óleo essencial de lavanda francesa é o mais conhecido, consumido e tradicional dentre todos. A lavanda acalma, tranquiliza e combate o estresse. Bastante indicado para terapias capilares, por sua ação calmante e cicatrizante. Atua diretamente no relaxamento do sistema nervoso e muscular. Proporciona alívio e descanso. Aut. Funcion. M.S.:2.05306.7 Proc. Nº: 25351.852526/2016-59', 88.96, 88.96, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd45-lwhldrd7d4htc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415568490%2F16710476169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40962641338', 'Kit 5x Biotina 100% Pura Pote 300 Cápsulas Bodyaction', 'Kit 5 Unidades – Biotina 100% Pura – Bodyaction Nutri Science A Biotina 100% Pura da Bodyaction Nutri Science foi desenvolvida para auxiliar no fortalecimento de cabelos, pele e unhas com eficácia e praticidade. Cada cápsula fornece 45 µg de biotina, garantindo a dose ideal para o uso diário. Este kit com 5 frascos oferece suplementação prolongada, mantendo a qualidade e confiança que a Bodyaction entrega. Benefícios: - Fortalecimento capilar: Contribui para cabelos mais fortes, resistentes e com brilho. - Saúde da pele: Ajuda a manter a pele saudável e equilibrada. - Fortalecimento das unhas: Auxilia na resistência e evita quebras e descamação. - Praticidade: Apenas 1 cápsula ao dia fornece a dose recomendada de biotina. Sugestão de uso: - Consumir 1 (uma) cápsula ao dia, preferencialmente com orientação de nutricionista ou médico. Ingredientes: - Biotina (D-Biotina) e antiumectante talco farmacêutico. Ingredientes da cápsula: HPMC (hidroxipropilmetilcelulose), água purificada e corante. Não contém glúten. Advertências: “ESTE PRODUTO NÃO É UM MEDICAMENTO.” “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM.” “MANTENHA FORA DO ALCANCE DE CRIANÇAS.” Conservação: - Armazenar em local fresco, seco e protegido da luz. Após aberto, consumir preferencialmente em até 60 dias. Não consumir o produto se o lacre de proteção estiver violado.', 210.0, 192.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rdwj-mddd3jfh3y0pc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662618933%2F40962641338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
