INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699270939', 'Kit 2 Suporte para Caixa de Som em Aço Reforçado Ajustável 6 Níveis Rotação 180 até 75kg', 'Kit 2x Suporte para caixas de som projetado para oferecer firmeza, segurança e praticidade na instalação, ideal para uso em ambientes residenciais, comerciais ou profissionais. Fabricado em aço reforçado, proporciona alta resistência e durabilidade, suportando equipamentos de grande porte com total estabilidade. Possui ajuste de comprimento em 6 níveis, permitindo regulagem precisa de acordo com a necessidade do espaço e do equipamento instalado. Conta com sistema de rotação e inclinação que facilita o direcionamento do som, garantindo melhor distribuição acústica no ambiente. Estrutura robusta e funcional, pensada para facilitar a instalação e o uso no dia a dia, mantendo o equipamento fixo e bem posicionado. ESPECIFICAÇÕES GERAIS: - Material: aço reforçado - Ajuste de comprimento: 6 níveis - Comprimento ajustável: 30 cm até 41 cm - Rotação: até 180 graus - Inclinação: até 45 graus - Capacidade máxima de carga: 75 kg - Tipo de uso: suporte para caixas de som CONTEÚDO: - 02 Suporte para caixa de som - Manual de instruções', 237.5, 173.02, NULL, 'Audio > Others', 'https://cf.shopee.com.br/file/sg-11134201-825zx-mj7hh3pxdr7n1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F22699270939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3169390049', 'Hhs2000 Wurth - Graxa Liquida Lubrificante Hhs 2000 Wurth', 'HHS2000 WURTH 200ml HHS 2000 é uma graxa líquida com alta capacidade de penetração em pequenas folgas, grande poder de adesão e resistência à pressão resultante da compressão. Possui baixo índice de gotejamento e com o aumento do atrito, a viscosidade aumenta progressivamente. A graxa passa do estado líquido para o estado pastoso, devido à evaporação do solvente. - Alta adesividade, quanto maior o atrito entre as partes, maior será a aderência. - Lubrifica partes expostas a alta pressão, impacto e vibração. - Resistente a altas temperaturas. - Grande capacidade de migração e penetração entre folgas médias. - Compatível com borrachas, silicones e plásticos. - Maior intervalo de re-lubrificação.', 95.92, 95.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/3a5bfaca10984ebc7f4e59bddcb5baae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F3169390049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10710384018', 'Boina De Espuma Vonixx Corte Leve Amarela 3'''' Para Polimento', 'BOINA AMARELA VOXER CORTE LEVE 3 POLEGADAS DESCRIÇÃO: Boina Voxer Corte Leve foi desenvolvida para remoção de defeitos mais leves. Proporciona um excelente nível de acabamento na superfície. Pode ser utilizada em máquina de roto-orbital ou rotativa.', 49.87, 49.87, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Pads', 'https://cf.shopee.com.br/file/2c671e888f64e0ce666788275cdd78e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F10710384018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
