INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19272095087', 'Filtro de Ar Pcx 150 2013-2018 / Click 125 Vedamotors', 'Filtro de Ar Vedamotors Os filtros de ar Vedamotors são projetados com todas as características necessárias para o excelente funcionamento do motor, filtrando quaisquer impurezas e deixando livre apenas a passagem de ar necessária para a melhor potência do motor com maior durabilidade. O papel utilizado nos filtros são mais densos, proporcionando maior grau de filtragem. Os filtros de ar da linha off-road da marca Athena, esses são fabricados com camadas de poliuretano de células abertas. Compatível com: HONDA CLICK 125 TODOS PCX 150 2013 A 2018 Vantagens: - Motor limpo (Livre de impurezas que possam comprometer o seu funcionamento de forma prematura) - Economia de combustível. O Filtro de ar Vedamotors é projetado com todas as características necessárias para o excelente funcionamento do motor, barrando quaisquer impureza e deixando livre apenas a passagem de ar necessária para a melhor potência do motor com maior durabilidade. Especificações Técnicas: - Qualidade em elementos filtrantes, desenvolvido para motores de alto desempenho; - Proporciona Melhor Queima de Combustível e Ajuda a Diminuir a Emissão de Gases Poluentes - Filtro Seco - Rigido - Oferece Menor Desgaste dos Componentes Internos do Motor - Maior Durabilidade e Qualidade de Filtração - Filtro de alto padrão desenvolvido com elementos filtrantes que equivalem as características técnicas exigidas pelos fabricantes de motocicletas - Fluxo de ar: Compatível com a especificação do fabricante - Não Lavável Importante: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 82.9, 66.32, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters',