INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19061907072', 'Filtro Cabine Ar Condicionado Honda Accord 2005 A 2017 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação ACCORD SEDAN EX 2.0 16V 156CV AUT. 2010 até 2012 ACCORD SEDAN EX 2.4/2.3/ 2.2 16V 2005, 2013 até 2014 ACCORD SEDAN EX 2.7/3.0 24V 2005 até 2007 ACCORD SEDAN EX 3.5 V6 24V 2008 até 2017 ACCORD SEDAN LX 2.2/2.4 16V 2005 ACCORD SEDAN LX 2.0 16V 150/156CV AUT. 2006 até 2009 Conteúdo Da Embalagem 1 Filtro de Ar Condicionado Cor do Produto No Tipo de Veículo para Carros Marca Fundada em 1969, a Wega Motors Brasil possui sede própria em Itajaí/SC, com uma moderna instalação que produz uma ampla gama de produtos para o mercado de reparação automotiva na linha leve e pesada. A Wega Motors é certificada em Sistema de Gestão da Qualidade ISO9001 – Versão 2000 (pelo BVQI – Bureau Veritas Certification), certificação essa que abrange a fabricação e comercialização de filtros de óleo, ar e combustível, velas e acessórios. O Produto O filtro de cabine é essencial para proteger a vida dos ocupantes, pois com o passar do tempo, microrganismos e poluentes presentes no ar, passam a representar um verdadeiro risco à saúde dentro do veículo. O filtro de cabine tem a função de filtrar impurezas presentes fora do veículo e circula no sistema de ventilação, inibindo sujeiras, gases tóxicos, e demais poluentes que entram em contato com o interior do veículo, contribuindo para a proliferação de doenças respiratórias, como sinusite, rinite, gripes, etc. A importância do uso de filtro de cabine aumenta em automóveis com ar-condicionado, já que os vidros permanecem fechados na maior parte do tempo. O filtro de cabine está instalado em diversos veículos fabricados a partir dos anos 2000, independente de possuírem ar-condicionado ou não. Sua troca vai depender dos locais em que você circula, já que alguns possuem mais poluição. A recomendação é verificar o filtro de cabine a cada 20 mil km rodados. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 • Valor unitário EAN 7798151949479 Código do Fabricante AKX1456 WEG >', 19.93, 19.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-llvvkoeorbdmda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F19061907072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
