INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299760567', 'Bola Basquete Poker Street Quadra Externa Tamanho Oficial Profissional FIBA Outdoor Resistente', 'Bola de Basquete Poker Street Nº7 Preto e Dourado CARACTERÍSTICAS: Marca: Poker Modelo: Street Nº7 Cor: Preto e Dourado Material: Borracha especial Circunferência: 75 a 78 cm Pressão recomendada: 7 - 9 libras Câmara: Butil Válvula: Removível Construção: 8 gomos A Bola de Basquete Poker Street Nº7 combina estilo e resistência para jogos intensos em áreas externas. Seu design em preto com detalhes dourados proporciona um visual marcante nas quadras. Fabricada com borracha especial e 8 gomos, oferece durabilidade e excelente aderência, mesmo em superfícies irregulares. Ideal para partidas de basquete de rua, esta bola garante precisão nos arremessos e controle durante o jogo. A câmara de butil mantém a pressão adequada por mais tempo, enquanto a válvula removível facilita a manutenção. BENEFÍCIOS: Durabilidade: Borracha especial resistente ao desgaste em superfícies ásperas. Precisão: Construção de 8 gomos que proporciona melhor controle e arremessos mais precisos. Estilo: Design preto com detalhes dourados que se destaca nas quadras. DIFERENCIAIS TÉCNICOS: Câmara de Butil: Mantém a pressão interna por mais tempo, reduzindo a necessidade de reenchimento frequente. O QUE ESTÁ INCLUSO? 1 Bola de Basquete Poker Street Nº7 Preto e Dourado O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes.', 188.38, 128.16, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Basketball', 'https://cf.shopee.com.br/file/sg-11134201-7rasd-mabphf463hifaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F19299760567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
