INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204967208', 'Colchão Inflável de Ar Solteiro 150kg para Barraca Camping Praia Reforçado Resistente Melhor Original + Bomba Manual', 'CARACTERÍSTICAS: -Marca: Bel -Modelo: Deluxe Comfort -Tipo: Colchão Inflável Solteiro -Cor: Cinza O Colchão Inflável Solteiro Bel Deluxe Comfort é a escolha certa para quem precisa de conforto e praticidade no camping. Ele entrega uma superfície estável para dormir melhor fora de casa, com montagem rápida e fácil de transportar, ideal para levar no carro, mochila ou usar como cama extra. Com design pensado para uso em viagens e atividades ao ar livre, ele ajuda a manter o descanso mais confortável após trilhas, praia ou acampamentos. A cor cinza também facilita o uso em diferentes ambientes sem aparentar sujeira com facilidade. BENEFÍCIOS: -Conforto no camping: melhora a qualidade do sono em barracas e áreas externas -Praticidade: fácil de encher, esvaziar e guardar -Versatilidade: útil também como cama extra em casa DIFERENCIAIS TÉCNICOS: -Design inflável: estrutura leve e compacta para transporte e armazenamento O QUE ESTÁ INCLUSO? 1 Colchão Inflável Solteiro Bel Deluxe Comfort Cinza + Bomba manual O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes', 286.83, 172.36, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-81ztf-mkjixwgfml8iee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F58204967208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993857802', 'Adesivo Lateral Opening Edition Toro 2017/ Emblema Da Porta', 'Adesivo Genérico._x000D_ Os emblemas automotivos além de determinar, em muitos casos, o modelo do veículo, também personalizam o seu carro e protegem a pintura. Os adesivos são produzidas em vinil automotivo autocolante importado, dispensando a utilização de produtos para a fixação e já possuem verniz automotivo. Dessa forma, as faixas estão protegidas da ação do tempo (Exposição ao sol e a chuva)._x000D_ _x000D_ Adesivo Lateral Opening Edition Toro 2017/ Emblema Da Porta _x000D_ _x000D_ CARACTERÍSTICAS:_x000D_ 2 Adesivos Opening Edition / Fabricado em Vinil Transparente / Dimensões: 29 x 4 cm_x000D_ _x000D_ Quantidade: 2 Adesivos Toro 2017/ Opening Edition_x000D_ _x000D_ Observações:_x000D_ Material autocolante._x000D_ Resistente à chuva e raios UV._x000D_ Embalagem segura para o transporte._x000D_ Vinil importado._x000D_ _x000D_ Instruções Para Aplicação:_x000D_ 1 - Limpe e remova qualquer impureza na área de aplicação do produto._x000D_ 2 - Limpe as mãos e remova o protetor do liner._x000D_ Procure ter o mínimo de contato com a face adesiva._x000D_ 3 - Centralize o produto no local da aplicação. Após esse posicionamento,_x000D_ pressione o produto gradativamente, sempre do centro para as bordas._x000D_ Procure retirar todas as bolhas._x000D_ 4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,_x000D_ pois isso danificará o produto._x000D_ _x000D_ OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo._x000D_ Recomendamos que a aplicação seja feita por um profissional._x000D_ _x000D_ Garantia de 1 ano.', 27.57, 25.92, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7reqk-m8261be6liv4d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F23993857802', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201106524', 'CD Rolling Stones - Black and Blue - Importado', 'CD Rolling Stones - Black and Blue - Importado CD com uma nova mixagem de 2025 de Steven Wilson, Black and Blue de 1976 é o álbum que introduziu Ronnie Wood aos Rolling Stones – com destaque em 3 faixas e se juntando à banda para a turnê mundial e os próximos 50 anos! Combinando suas influências de reggae e funk com sua arrogância rock and roll, eis a maior banda de rock de todas, com riffs de funk desfilando em "Hot Stuff" e rockers de tirar o fôlego como "Hand of Fate", misturando-se com as memoráveis ??baladas de "Fool To Cry" e a favorita dos fãs, "Memory Motel". Tracklist: 1CD - Steven Wilson Remix 2025 1. Hot Stuff 2. Hand Of Fate 3. Cherry Oh Baby 4. Memory Motel 5. Hey Negrita 6. Melody 7. Fool To Cry 8. Crazy Mama', 109.9, 82.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8257u-mqnkmk3z1w5ff3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58201106524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
