INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16012848405', 'Ração Royal Canin para Cães Adultos da Raça Shih Tzu - 1Kg', '- Ração de qualidade Super Premium; - Indicada para cães da raça Shih Tzu, adultos (com mais de 10 meses de idade); - Exclusiva combinação de nutrientes que garantem uma ótima digestão e um bom equilíbrio da flora intestinal; - Estimula a mastigação, favorecendo a saúde dental e evitando o acúmulo de placa bacteriana ("tártaro"); - Cuida da saúde da pele e pelagem a partir de fontes de ômega 6; - Reduzir o volume e o odor das fezes.', 83.06, 66.45, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/ebdcafef70e4ef1304dfb9e6abea4f0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F16012848405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25442045462', 'Cute & Comfy Super Extra Edição 04 - Livro de Colorir Adulto - Capa Dura Holográfica', 'Cute & Comfy Super Extra – O livro de colorir perfeito para relaxar! Se você ama momentos de tranquilidade e adora colorir, o Cute & Comfy Super Extra é a escolha ideal. Inspirado no fenômeno do TikTok, este livro traz 40 ilustrações encantadoras, prontas para ganhar vida com lápis de cor ou marcadores, proporcionando uma experiência relaxante e prazerosa. Por que você vai se apaixonar? 40 ilustrações exclusivas – Desenhos feitos à mão, esperando por suas cores. Traços amplos e fáceis de preencher – Perfeito para um colorir descomplicado e revigorante. Formato compacto (22,0 x 16,0 cm) – Ideal para levar para onde quiser. Encadernação espiral Wire-O – Abre totalmente para mais conforto ao colorir. Impressão premium – Linhas nítidas e detalhadas para um acabamento impecável. Acabamento de luxo – Capa dura com efeito holográfico deslumbrante. Seja para se presentear ou surpreender alguém especial, este livro transforma o simples ato de colorir em um verdadeiro momento de terapia e bem-estar. Relaxe, solte a criatividade e aproveite cada página.', 59.9, 14.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-m6sf0iyy2ejlf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F25442045462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29235648330', 'Além do Bem e do Mal - Edição de Luxo Almofadada', '"Além do Bem e do Mal" é uma obra fundamental da filosofia do século XIX, onde Friedrich Friedrich Nietzsche realiza uma ruptura profunda com a tradição filosófica ocidental. O livro desafia as convenções morais da sociedade, que o filósofo considera limitadas e ultrapassadas. Friedrich Nietzsche critica a moralidade de rebanho, que, segundo ele, suprime a individualidade e a criatividade, propondo, em seu lugar, uma nova moralidade baseada na vontade de poder e na afirmação da vida. A obra é não apenas uma reflexão filosófica, mas também uma subversão dos valores estabelecidos, tornando-se um marco no pensamento ocidental e um convite à reavaliação dos fundamentos da moralidade e da liberdade individual. Influente e controversa, "Além do Bem e do Mal" se consolidou como uma das leituras obrigatórias para os amantes da filosofia. Esta edição de luxo se destaca pelo seu acabamento refinado, proporcionando uma experiência de leitura tanto estética quanto intelectual: Capa Almofadada almofadada, que garante resistência e um toque sofisticado. Acabamento em hot-stamping, com detalhes dourados que realçam a elegância da obra. Lateral tie-dye dourada, conferindo um charme adicional e um visual deslumbrante. Marcador de fitilho, para acompanhar a leitura com estilo e praticidade. Uma edição de luxo que torna a obra ainda mais impactante, perfeita para os colecionadores e para aqueles que desejam apreciar a profundidade filosófica de Friedrich Nietzsche com todo o requinte. DESCRIÇÃO Editora: Editora Garnier Edição: 1, 2025 Autor: Friedrich Nietzsche Idioma: Português Páginas: 192 Dimensões: A 23 x L 15,1 x E 2,5 Encadernação: Capa Almofadada ISBN: 9786584956971', 69.9, 59.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rfgf-m97r5ahu7jk0a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F29235648330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
