INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43123699394', 'Lanterna Caneta Recarregável 3,5 W LED CREE LCR 350 Vonder', '***PRODUTO PRONTA ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL Conteúdo da Embalagem: 1 Lanterna. Acompanha: 1 cabo USB tipo C. Possui três níveis de luminosidade: modo econômico, baixo e alto. Indicada para iluminação em geral. Utilizada em camping, residências, entre outros. Garantia legal: 90 dias Modelo: LCR 350 Material da lanterna: Alumínio, plástico e borracha Cor da lanterna: Preta Comprimento total da lanterna:152 mm Diâmetro da lente da lanterna:ø10 mm Tipo de lâmpada: Led Cree Fluxo luminoso (lm):Modo econômico: 5 lúmens/ Modo baixo: 100 lúmens/ Modo alto: 350 lúmens Duração aproximada da bateria: Nível 1 (ECO): 35 horas/ Nível 2 (LOW): 6,5 horas/ Nível 3 (HIGH): 2 horas e 50 min Tensão:5 V DC / 1 A (cabo USB) Tempo de carga:2 horas e 30 minutos Massa aproximada (peso):0,475 kg', 238.9, 238.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-820m2-monzl4w6pmgw0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F43123699394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
