INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203313700', 'Eudora Kit Siàge Cauterização dos Lisos: Shampoo 250ml + Condicionador 200ml + Leave-in 100ml', 'O Combo Siàge Cauterização dos Lisos: Shampoo + Condicionador + Leave-in deixa os fios alinhados, disciplinados e macios, além de resistentes e hidratados, desde o primeiro dia de uso. SHAMPOO O Shampoo Siàge Cauterização dos Lisos trata os danos antes e depois do processo de alisamento. Sua fórmula com Amino10-effex e Proteína Hidrolisada fortalece as fibras capilares, repõe os nutrientes e protege os fios contra as agressões externas. CONDICIONADOR O Condicionador Siàge Cauterização dos Lisos disciplina, alinha, hidrata e desembaraça os fios diariamente. Com fórmula inteligente, entrega uma explosão de fragrância, que resiste ao calor do secador e da chapinha. LEAVE-IN O Leave-in Capilar Siàge Cauterização dos Lisos entrega fios fortes, protegidos do calor e com muito movimento. Age profundamente garantindo cauterização e selagem imediata, para cabelos 3x mais lisos, anti-frágeis e protegidos. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 157.97, 157.97, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-8261z-mjhshotjkohs28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58203313700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
