INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494506747', 'FLANGE DA BOMBA DE COMBUSTIVEL Gol/G2 /Parati/Saveiro Mi 95', 'Flange de Bomba de Combustível para Gol / Parati / Saveiro Mi 95/ Todos G2 - Gasolina com Engate A Flange de Bomba de Combustível é uma peça fundamental para o funcionamento adequado do sistema de alimentação de combustível. Este modelo foi projetado especialmente para os veículos Volkswagen Gol, Parati e Saveiro Mi, fabricados a partir de 1995 (Geração 2), que utilizam sistema de injeção eletrônica e combustível gasolina. Especificações do Produto: Aplicação: Gol / Parati / Saveiro Mi 95/..., Todos G2 (Gasolina) Número Original de Referência: Compatível com as especificações originais da Volkswagen Tipo de Combustível: Gasolina Sistema: Injeção eletrônica (Mi) Com Engate: Facilita a conexão e instalação segura da bomba de combustível Material: Plástico reforçado de alta qualidade, resistente à corrosão e às variações de temperatura Diâmetro Externo: Aproximadamente 120 mm Espessura: Aproximadamente 10 a 12 mm Comprimento (Altura): Aproximadamente 30 a 40 mm Peso: Em torno de 150 g Vedação de Alta Eficiência: Garante proteção contra vazamentos e proporciona o encaixe perfeito no tanque de combustível. Benefícios: Fácil instalação, mantendo o padrão de fábrica sem necessidade de adaptações Acompanha engate, proporcionando uma fixação segura e rápida Material durável e resistente, garantindo maior vida útil ao sistema de combustível Produto compatível com os modelos da linha Volkswagen Geração 2 (Gol, Parati e Saveiro) Este descritivo realça as características principais, o modelo de aplicação e o benefício de ter engate para fácil instalação. 90 DIA DE GARANTIA.', 33.9, 33.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/fi