INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698868592', 'Sabonete Líquido Nivea Erva Doce Refil 200ml', 'Recomendações de Uso: 1. Massageie o sabonete sobre a pele molhada até formar espuma. 2. Enxágue em seguida. Uso externo. Evite contato direto com os olhos. Caso aconteça, enxague com água em abundância. Em caso de irritação, suspenda o uso e procure orientação médica. Manter em local seco e arejado, ao abrigo de luz e fora do alcance de crianças.', 20.24, 20.24, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-824he-mpiadbef9edd9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23698868592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
