INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494961873', 'Salsicha Hot Dog Seara', 'A Salsicha Hot Dog Seara é produzida com carnes de qualidade e tem um sabor temperado no ponto certo, perfeita para o seu cachorro-quente e lanches rápidos! Modo de Preparo: Em uma panela, ferva água, após fervura, coloque as salsichas e deixe cozinhar por 3 minutos. Ingredientes: Carne mecanicamente separada de frango, carne suína, carne de frango, água, proteína de soja, pele de frango, fécula de mandioca, sal, dextrose, pimenta-branca, cebola, pimenta-da-Jamaica, açúcar, aromas naturais e aromas idênticos aos naturais, estabilizantes, realçador de sabor glutamato monossódico, antioxidante eritorbato de sódio, corantes: carmim de cochonilha e urucum, conservante nitrito de sódio.', 11.49, 11.49, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zwt-miyqaa6s92bm30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290582%2F22494961873', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
