INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208000041', 'Pegasus Seiya Manga Setting – Saint Seiya – Champion Class – Blokees', 'O Pegasus Seiya Manga Setting da linha Champion Class da Blokees traz o Cavaleiro de Pégaso em uma representação inspirada diretamente no visual do mangá, destacando sua essência heroica e determinação em batalha. A peça apresenta escultura fiel, proporções marcantes e uma pose que transmite ação e coragem. Com acabamento detalhado e design expressivo, esta figura é ideal para fãs de Saint Seiya e colecionadores que buscam uma representação autêntica e impactante de um dos personagens mais icônicos do anime.', 229.9, 229.9, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-8262i-mmhy9xmpqjurf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191775191%2F58208000041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498148955', 'Etiquetas Artesanais Pão de Mel Artesanal - 4cm - 12 unidades - Rizzo Confeitaria', '🎁 Etiquetas Artesanais Pão de Mel Kraft ideal para montar presentes e kits com uma apresentação elegante e diferenciada! O Etiquetas Artesanais Pão de Mel Kraft combina funcionalidade e qualidade, sendo uma excelente escolha para quem busca praticidade e um ótimo resultado no uso diário. Descrição Técnica: Produto: Etiquetas Artesanais Pão de Mel Modelo: Kraft Quantidade: 12 unidades Marca: Rizzo Confeitaria Dúvidas Frequentes: Quanto tempo leva o envio? ⏰ Todos os pedidos com etiqueta de envio liberado pela shopee até as 18hs são coletados no próximo dia útil pela transportadora Shopee Express. Qual o prazo de entrega? 🛵 A loja não tem acesso a parte logística da shopee. A Shopee não informa para a loja prazo de entrega. Ao clicar em comprar na opção envios é apresentado o prazo de entrega. O produto é novo? 😀 Sim. Só trabalhamos com produto novos e dentro da embalagem original do fabricante. Como faço para comprar mais de um item da loja? 🛍 No app ao lado do botão comprar tem o ícone de um carrinho de supermercado, clicando nele o produto será acrescentado no carrinho que fica na parte superior do app. Após acrescentar todos os produtos que gostaria é só clicar no carrinho e selecionar todos os itens e clicar em continuar. Comemore com Alegria: 🥰😀 Na Rizzo Distribuidora, a tradição e o encanto do nosso espaço físico no coração da 25 de março, em São Paulo, são cuidadosamente embalados para chegar até você. Permita-nos levar a magia de uma das lojas mais tradicionais da região diretamente para o conforto da sua casa ou empresa.', 10.9, 10.9, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra1o-m51vw9zzcnsbd3', 'https://shope.ee/an_r