INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23602204646', 'Base Sommier Preto Solteiro (88x188x23) - Ortobom', 'A Base Sommier Preto Solteiro (88x188x23) - Ortobom é a perfeita combinação com os Colchões Ortobom, indicado para pessoas de até 150kg cada (além do peso do colchão), revestimento em Material Sintético, possui 36cm de altura (23cm da Base + 13cm dos pés). Toda sua estrutura é em madeira Eucalipto Domus com bactericida natural que evita proliferação de cupins, brocas e traças. Acompanha jogo de Pés. Possui tratamento antialérgico e antiácaro. Características: Estrutura em madeira de reflorestamento, espuma Pró Aditivada com Poliol a Base Sommier de Soja, Revestido em Material Sintético. Acompanha jogo de pés em PVC. Informações Técnicas: -Estrutura Interna: Estrutura em madeira Eucalipto Domus de Reflorestamento. -Estrutura Externa: Revestimento em Material Sintético -Cor: Preto -Altura: 23cm - Largura: 88cm - Comprimento: 188cm -Capacidade de suporte: Até 150kg por pessoa -Acompanha: 1 Base Sommier Ortobom + kit pés + Manual Importante: Ideal a contratação de um montador profissional. Garantia 12 Meses contra defeitos de fabricação', 569.99, 499.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-22100-sa67bmfq34iv44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23602204646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
