INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46203555692', 'Sache Chá Low Tox ( Detox ) 15g - CHAMEL', 'O Chá Low Tox combina o frescor do chá verde, a doçura suave da maçã, a força da carqueja, a vitalidade do espinafre, o toque picante do gengibre e a delicadeza do goji berry. Cada gole traz uma sensação de leveza e renovação, como se o corpo respirasse melhor e a rotina ganhasse momentos de equilíbrio, frescor e bem-estar. Benefícios: ✅ Combinação equilibrada de ingredientes naturais ✅ Sensação de leveza e renovação a cada xícara ✅ Frescor do chá verde com notas frutadas e herbais ✅ Ajuda a trazer bem-estar e equilíbrio ao dia ✅ Aroma agradável e sabor refrescante ✅ Perfeito para momentos de pausa ou rotina intensa Ficha Técnica: ✅ Produto: Chá Low Tox ✅ Ingredientes: Chá verde, maçã, carqueja, espinafre, gengibre e goji berry ✅ Indicação: Leveza, frescor, bem-estar e equilíbrio diário ✅ Modo de preparo: Infusão em água quente ✅ Ideal para qualquer horário do dia', 12.14, 12.14, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/sg-11134201-81zud-mily5slke1ojca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F46203555692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
