INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393829812', 'Kit 6 und Complexo B 100 Cpr Arte Nativa', 'Kit 6 und Complexo B -100 CprAs vitaminas do Complexo B são um grupo de oito vitaminas: Tiamina (B1), riboflavina (B2), niacina (B3), ácido pantotênico (B5), piridoxina (B6). Estas vitaminas são essenciais para a decomposição química de carboidratos em glicose, fornecendo energia para o organismo; para a decomposição química das gorduras e proteínas, ajudando no funcionamento normal do sistema nervoso; e para o tônus muscular no estômago e no trato intestinal.', 83.51, 83.51, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd4p-m7gnx9p51hueb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23393829812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398654123', 'Esfoliante Corporal e Facial Labotrat Pitaya 150g', 'Esfoliante Corporal e Facial Labotrat Pitaya 150g O Esfoliante Corporal Pitaya Dia a Dia 150g da Labotrat é a escolha ideal para quem busca prevenir e combater a flacidez enquanto desfruta de uma pele macia e aveludada. Formulado com NANO DMAE, promove firmeza e renovação celular, deixando sua pele suave e revitalizada. Com uma fragrância delicada de pitaya, ele proporciona um cuidado diário eficaz e um toque sedoso. Aposte no cuidado completo para sua pele com esse esfoliante poderoso e sinta a diferença desde a primeira aplicação!', 21.46, 18.9, NULL, 'Beauty > Bath & Body Care > Body Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-7ratk-mayk5p0k52z49d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22398654123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
