INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997417143', 'Blusa Básica Feminina Manga Longa Slim', 'Blusa básica feminina manga longa slim, esta peça faz parte da nossa linha de básicos. São itens essenciais e versáteis que podem ser coordenados entre si e combinam com todo o seu guarda-roupa. Elaborada em malha de algodão e elastano, possui silhueta acinturada, decote v e mangas longas. Prática e versátil, ideal para compor várias propostas de looks para o seu dia a dia.Detalhes da peça:Malha de algodãoModelagem slimManga longaDecote V', 99.99, 99.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-824j9-meysif5fmex4e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F22997417143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260131479', 'Polo Masculina Esportiva Com Bordado Drop Brasil', 'DROP BRASIL: A fusão do básico com a paixão nacional em uma coleção atual e versátil. Inspirada na energia da torcida brasileira, traz estampas contemporâneas e design moderno que combinam o espírito do futebol com o estilo casual. Ideal para usar nos dias de jogo e também no dia a dia, levando a energia do Brasil para qualquer ocasião.Polo masculina em malha binada de algodão com estampa localizada e bordado. Inspirada em uniformes de futebol, esta peça une estilo e atitude, ideal para a temporada. Modelagem regular para um caimento perfeito e frisos contrastantes adicionam um toque esportivo único. Esta polo é a escolha perfeita para compor looks casuais com personalidade. Sua versatilidade permite transitar entre eventos esportivos e encontros descontraídos, sempre com conforto e um visual autêntico. Detalhes da peça: Malha binada de algodãoEstampa localizadaBordado frontalGola contrastanteModelagem regular', 159.99, 89.99, NULL, 'Men Clothes > Tops > Polo Shirts', 'https://cf.shopee.com.br/file/sg-11134201-820ld-mnvopy2u4xdu5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F58260131479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
