INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797988642', 'Tênis Infantil Menino Calce Fácil Escolar Confortável Original Branco/Preto/Vermelho', 'Tamanho (BR) | Comprimento N° 22 - 15 cm N° 23 - 15,5 cm N° 24 - 16,7 cm N° 25 - 17,5 cm N° 26 - 18 cm N° 27 - 18,5 cm Se você está procurando o calçado perfeito para os pequenos aventureiros, o tênis casual masculino infantil é a escolha ideal! Combinando conforto, durabilidade e estilo, esses tênis foram projetados para acompanhar o ritmo acelerado das crianças, seja na escola, no parque ou em casa. Uma das grandes vantagens desses tênis é o conforto que proporcionam. Com materiais leves, eles garantem que os pezinhos fiquem bem protegidos, mesmo durante horas de brincadeira. As crianças podem correr, pular e explorar o mundo sem se preocupar com desconfortos! Além disso, os tênis casuais masculinos são super versáteis. Com designs modernos e cores variadas, eles se adaptam a qualquer estilo e podem ser facilmente combinados com diferentes roupas, desde jeans e shorts até bermudas. Seu filho estará sempre na moda, pronto para arrasar em qualquer ocasião!', 99.9, 59.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8z6p3vivgua60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296584125%2F23797988642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
