INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6889037399', 'Bomba Absolute Prime Azul c/ Mangueira', 'Modelo leve e compacto para praticantes amadores e profissionais de ciclismo, com design elegante e construção em alumínio. Possui uma pequena mangueira para conexão com a válvula, o que tira o stress normal da cabeça da bomba sob o corpo da válvula e ainda aumenta a eficácia da inflação dos pneus pelo usuário. Especificações Bomba Mini-Pump Giyo GP-871E; Corpo em alumínio Polido; Com manômetro e Conexão 360°; Mangueira retrátil; 120 PSI; Bico reversível para válvula presta e schrader com alavanca de trava. Acompanha suporte para instalação no quadro.', 124.9, 124.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/724199b498e95f30d89a7e574885bd33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F6889037399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7789032129', 'Meia Cano Longo ERT Azul', 'Um dos acessórios mais usados entre os ciclistas, a meia é um produto que serve além da proteção, também para completar o fardamento. Feita de fio de poliamida, material resistente, leve e muito confortável. Possui telas de respiro na sola e parte superior dos pés, facilitando a troca térmica e evitando que o pé fique muito úmido. Possui tratamento bactericida com íons de prata, que afasta as bactérias, evitando odores indesejáveis.', 29.9, 29.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Others', 'https://cf.shopee.com.br/file/e5cceb834ac8fdf9b9a9e97d92f6f0b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F7789032129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
