INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692670295', 'Puxador De Porta Preto Madeira Vidro 60cm Inox 304 Fosco', 'PUXADOR RETO 60CM PRETO BRINOVAR Puxador é um acessório essencial para facilitar a abertura da porta, além de contribuir para a decoração com um visual moderno. Resistente, pode ser utilizado em regiões litorâneas e exposto a sol e chuva sem riscos de manchas ou ferrugem, graças ao seu material de aço inox com acabamento escovado, adequado para diversos modelos de portas, como pivotante, de madeira, de vidro, de alumínio, de aço, de correr e portões. ESPECIFICAÇÕES TÉCNICAS: Marca: BRINOVAR Material: Aço Inox 304 Cor: Preto Acabamento: Fosco Formato: Reto Instalação: Área interna ou externa Medida total do puxador: 60cm Medida entre furos: 40cm Largura do Puxador: 4cm Espessura da Barra: 1cm Suporte de fixação redondo Garantia: 90 dias CUIDADOS: Não use palha de aço, produtos químicos, não usar ácido muriático, água sanitária ou qualquer outro solvente para a limpeza. Limpe periodicamente o seu produto apenas com um pano macio, água e sabão neutro. Para manter o brilho do seu produto recomendamos o uso da pasta para polir e remover manchas em superfícies de aço inoxidável. ITENS INCLUSOS: 1 Par de puxador 60cm, lado de dentro e lado de fora 1 Chave allen Parafusos para instalação', 160.0, 131.47, NULL, 'Home & Living > Safety & Security > Door Hardware & Locks', 'https://cf.shopee.com.br/file/sg-11134201-7rbmx-lq934bifejl608', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1029852536%2F23692670295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13667827808', 'Coloração Super Bonita 8.0 - Louro Claro Probelle probelle', 'COLORAÇÃO SUPER BONITA A Coloração Super Bonita Probelle 50g possui desenvolvimento revolucionário com os 6 óleos mais essenciais: Óleo de argan, óleo de linhaça, óleo de lotus, óleo de girassol, óleo de semente de uva e óleo de castanha do Pará. A Coloração Super Bonita promove resultado surpreendente de cor vibrante., Nutrição em profundidade, reposição imediata de aminoácidos e proteínas com ação energética. Advertências: É indispensável seguir corretamente as indicações de uso e modo de preparo no folheto explicativo, no interior deste cartucho. Utilizar as luvas contidas neste kit. Não utilize se já teve alguma reação de produto de coloração. Não aplique se o couro cabeludo apresentar lesões ou irritações.', 12.9, 12.9, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-22120-qjnva3gwtmlv11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F13667827808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
