INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697747790', 'Você é o Melhor De Deus | T. L. Osborn', 'Autor(es): T. L. Osborn ISBN: 978-85-7343-972-4 Número de Páginas: 144 Tamanho: 14x21 cm Peso: 0,200 Após quatro décadas de ensinamentos a milhões de pessoas, face a face, em mais de 75 nações, Dr. T. L. Osborn e sua esposa e colega de ministério, Dra. Daisy Washburn Osborn, descobriram os sete segredos ou princípios básicos vitais sobre o melhor de Deus na vida. Os fundamentos têm sido testados e provados na arena viva da experiência humana pelo mundo afora. Os Osborn os têm ensinado a budistas, maometanos, xintoístas, hindus, animistas, macumbeiros, cristãos e ateus – a pessoas das principais religiões e culturas do mundo. “Escrevi este livro para ajudá-lo a descobrir que você é o melhor de Deus. Há um censo de destino na sua vida porque você é a ideia de Deus, o Seu sonho”, esclarecer o autor.', 30.9, 30.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdx2-lzv4d26rw1ew90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23697747790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49057570561', 'Bagageiro Factor E Fazer 150 2017 A 2025 Suporte P/ Bau Bagageiro Grelha Churrasqueira', '🏍️ ESPECIFICAÇÕES – BAGAGEIRO FAZER 150 / FACTOR 150 ✔️ Compatibilidade Yamaha Fazer 150: 2017 a 2023 Yamaha Factor 150: 2017 a 2025 (Compatível também com Factor 125 2017+ em muitos modelos) ✔️ Material e Construção Fabricado em aço carbono de alta resistência Estrutura tubular Pintura eletrostática (maior durabilidade contra ferrugem) ✔️ Instalação Fixação nos pontos originais da moto Instalação simples (sem necessidade de adaptação) ✔️ Características Modelo: churrasqueira / suporte de baú Cor: preto Alta resistência e durabilidade Não interfere no banco do passageiro Design discreto e funcional', 310.9, 188.63, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/br-11134207-820mg-mm53ep7oy8ljb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1471063820%2F49057570561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10962498782', 'O líder emocionalmente saudável - Peter Scazzero', 'Em O líder emocionalmente saudável, o premiado autor Peter Scazzero mostra aos líderes como desenvolver uma profunda vida interior examinando suas implicações com relação ao planejamento e tomada de decisão, formação de equipes, criar cultura saudável, influenciar outras pessoas, e muito mais. • Avaliações concisas para líderes e equipes medirem a saúde de sua liderança • Estratégias práticas e comprovadas desenvolvidas por um período de mais de 28 anos tanto na igreja local como no preparo de líderes no mundo todo • Exemplos práticos de como enfrentar sua sombra, desfrutar seu casamento ou vida de solteiro, reduzir o ritmo e aceitar os finais em favor de novos começos "Um recurso extraordinário com ideias exequíveis, pragmáticas, revolucionárias em sua abordagem, tocando as dores mais profundas da liderança com bálsamo para a alma". – Bispo T. D. Jakes Sr., TDJ Enterprises, New York Times autor best seller "Peter Scazzero é uma das autoridades mundiais sobre saúde emocional [...] oferecendo nova esperança a qualquer um que busque crescer e se desenvolver como líder." – Nicky Gumbel, Holy Trinity Bromptom, UK; "pioneiro do curso Alpha Profundamente útil, perspicaz e com notável honestidade, Pete nos inspira a apresentar nossos egos às comunidades às quais servimos para a glória de Deus." – Dra. Ruth Haley Barton, fundadora e presidente do Transforming Center e autora de Strengthening the Soul of Your Leadership O líder emocionalmente saudável oferece uma integração única, inovadora que liga nossa vida espiritual interna com tarefas fundamentais de liderança, tais como planejamento, tomada de decisão, formação de equipes, estabelecimento de limites, administração de relações complexas, exercício do poder e aceitação de términos em favor de novos começos. 320 Páginas 16x23cm', 36.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/9da1c77caea833a629c6fa6304b4a350', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F10962498782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8010693253', 'Cabo Rca 5 Metros Simples Emborrachado Som Audio Vídeo', 'Kit Cabo RCA 5 Metros para Som Automotivo Disponível na cor preta Revestimento em pvc flexível Mono blindagem Condutor de cobre isento de oxigênio (ofhc) Alta capacidade de condução Diminui interferências na transmissão de áudio ou vídeo11 Espessura: 5mm Comprimento: 5 metros Plugs banhados a ouro Conteúdo da embalagem: 01 - Unidades do cabo rca 5 metros Garantia: 3 Meses da Garantia contra defeito de Fabricação. OESTESOM A MELHOR LOJA DE PRODUTOS AUTOMOTIVOS NA INTERNET!!!', 30.33, 26.97, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/3af26b70ef17d6c065e795ef2d551766', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F8010693253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20202041694', 'Ser Pastor | Alistair Begg Derek Prime', 'O ofício de maior responsabilidade humana em toda a criação. SER PASTOR Entendendo nossa vocação e obra DEREK PRIME & ALISTAIR BEGG - Com Prefácio de Albert Mohler O ministério dos pastores não é simplesmente um trabalho. É uma vocação e um estilo de vida. As responsabilidades de um pastor são únicas, exigindo que ele não só nutra sua própria vida espiritual, mas também a vida dos que estão sob seus cuidados. Que desafio! Derek Prime e Alistair Begg fornecem conselhos práticos para os aspectos espirituais e práticos do ministério pastoral. Eles se aprofundam em temas como oração, hábitos devocionais, pregação, estudo e tarefas específicas do ministério. O resultado é uma ferramenta essencial para os pastores pastorais. "Ser pastor é um elevado chamado que requer devoção, habilidade e preparação espiritual única. Derek Prime e Alistair Begg fornecem clareza para o chamado, sabedoria para a viagem e experiência para a tarefa. Este livro é como uma conversa com bons amigos que não fornecem conselhos absurdos para os desafios do ministério do século 21." - Jack Graham, Pastor, Prestonwood Baptist Church, Dallas, Texas "Ser Pastor é um livro notável, que deve estar na estante de cada pastor. Eu li e consultei a versão anterior de Derek Prime por muitos anos. Agora foi revisado e enriquecido com a colaboração de Alistair Begg, e o resultado é esplêndido!" - Eric Alexander, Igreja Paroquial de São Jorge – Tron, Escócia Derek Prime, nascido em 1931, pastoreou igrejas no Reino Unido por trinta anos, primeiro na Lansdowne Evangelical Free Church, West Norwood, em Londres; e depois em Charlotte Chapel em Edimburgo. Dedicou-se desde 1987 a um ministério itinerante e a escrever. Alistair Begg, nascido em 1952, é o pastor titular da Parkside Church de Cleveland, posição que assumiu em 1983. Ele é a voz por trás da Truth for Life, ministério cristão de pregação e ensino que transmite seus sermões diariamente para estações em todo os Estados Unidos. É o autor de vários livros. 256 Páginas 16x23cm', 69.9, 45.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/037325de24619155a90e6523c93108a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20202041694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393279079', 'Sylvanian Families Gêmeos Huskys Passeio De Trem - Epoch 5638', 'Os Gêmeos Huskys Com Trenzinho Epoch 5638 da marca Sylvanian são perfeitos para crianças a partir de 4 anos. Feitos de plástico resistente, eles garantem diversão duradoura. Com um design cinza encantador, esses adoráveis gêmeos vêm acompanhados de um trenzinho para passeios divertidos. Recomendado para crianças de até 99 anos, esse conjunto é ideal para estimular a imaginação e criatividade dos pequenos. Garanta já esse brinquedo incrível para presentear ou colecionar.', 149.9, 109.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m08ywwj69xvh37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F23393279079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699882691', 'Kit com Carregador Bivolt ICBD1805 e Bateria 18V 2Ah IBD1802 DWT', 'O Kit DWT com Carregador ICBD1805 Bivolt e Bateria 18V 2Ah IBD1802 é indicado para ferramentas a bateria da linha intercambiável DWT 18V, oferecendo praticidade para reposição, uso extra ou substituição de bateria e carregador. O carregador possui entrada bivolt automática, carregamento convencional e saída de 20V. A bateria é de íons de lítio, com tensão de 18V e capacidade de 2,0Ah, ideal para manter suas ferramentas da linha DWT sempre prontas para o uso. Diferenciais do Produto: ✅ Kit com carregador bivolt e bateria 18V ✅ Compatível com ferramentas da linha intercambiável DWT 18V ✅ Carregador com bivolt automático 100V a 240V ✅ Bateria de íons de lítio com 2,0Ah ✅ Indicador de bateria fraca ✅ Ideal para reposição ou bateria extra ✅ Carregamento convencional seguro e prático ✅ Produto leve e fácil de transportar **Detalhes Técnicos do Carregador** Marca: DWT Modelo: ICBD1805 Tipo de produto: Carregador de bateria Tensão de entrada: 100 V~ - 240 V~ bivolt automático Frequência: 50 Hz / 60 Hz Tipo de carregamento: Convencional Tensão de saída: 20 V Corrente de saída: 2,3 A Tempo de carregamento bateria 2.0Ah: 60 minutos Tempo de carregamento bateria 4.0Ah: 120 minutos Massa aproximada: 0,444 kg **Detalhes Técnicos da Bateria** Marca: DWT Modelo: IBD1802 Tipo de bateria: Íons de lítio Tensão: 18 V Capacidade: 2,0Ah Indicador de bateria fraca: Sim Massa aproximada: 0,428 kg Conteúdo da Embalagem ✔️1 Carregador de bateria ICBD1805 ✔️1 Bateria 18V 2Ah IBD1802', 392.0, 319.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824ib-mesq71amff286b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F18699882691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
