INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209095519', 'Manta Fleece Microfibra 180g Vêneto Fend', 'A Manta Fleece Vêneto é ideal para quem busca conforto e aconchego no dia a dia, com um toque extremamente macio e aveludado que envolve o corpo com suavidade. Produzida em microfibra fleece, proporciona uma experiência agradável tanto para momentos de descanso quanto para uso decorativo. Com gramatura de 180 g/m², oferece o equilíbrio perfeito entre leveza e aquecimento, sendo ideal para noites mais frescas ou para relaxar no sofá. Suas dimensões versáteis garantem excelente cobertura, adaptando-se facilmente a diferentes tamanhos de cama. Além do conforto, seu visual elegante combina com diversos estilos de decoração, agregando sofisticação ao ambiente. Composição: Microfibra 100% Poliéster Gramatura: 180 g/m² Tamanhos disponíveis: Solteiro: 150 x 220 cm Casal: 180 x 220 cm Queen: 220 x 240 cm Diferenciais: Toque extra macio e aveludado Leve e confortável para uso diário Ideal para dias mais frescos e meia-estação Versátil: pode ser usada na cama ou sofá Fácil de combinar com diferentes estilos de decoração Cuidados: Seguir as instruções de lavagem indicadas na etiqueta do produto. Observação: As cores podem apresentar variações sutis de acordo com o lote de fabricação e/ou configurações de tela.', 59.9, 59.9, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/sg-11134201-81zu5-mn5wfug8mltwf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F58209095519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
