INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51061829838', 'Dr.Althea 345 Relief Serum 30ml', 'Dr.Althea 345 Relief Serum 30ml Um sérum calmante e hidratante formulado com Niacinamida, Pantenol, Extrato do Caule de Opuntia Ficus-Indica, ingredientes derivados da Centella e componentes que ajudam a fortalecer a barreira cutânea, auxiliando no alívio da pele sensibilizada, reposição da hidratação e melhora da condição geral da pele, com um acabamento leve e não pegajoso. ✨ POR QUE VOCÊ VAI AMAR 🌿 Cuidado Calmante Intensivo 👉 Ajuda a acalmar a pele afetada por agressões externas e irritações temporárias 👉 Promove uma pele mais equilibrada e confortável 💧 Hidratação Profunda 👉 Fornece hidratação leve para a pele desidratada 👉 Ajuda a manter a hidratação por mais tempo 🛡️ Fortalecimento da Barreira Cutânea 👉 Ajuda a proteger e fortalecer a barreira natural de hidratação da pele 👉 Reduz a sensação de ressecamento e repuxamento ✨ Niacinamida para Condicionamento da Pele 👉 Ajuda a melhorar a aparência do tom de pele irregular 👉 Promove uma pele mais uniforme e saudável 🌵 Cuidado com Extrato de Opuntia Ficus-Indica 👉 Proporciona benefícios hidratantes e calmantes 👉 Ajuda a manter a pele macia e revitalizada 🫧 Fórmula Leve para Uso Diário 👉 Textura sérum de rápida absorção 👉 Deixa a pele confortável sem sensação pegajosa 💡 TEXTURA E ACABAMENTO Textura leve de sérum Absorção rápida Sensação não oleosa Acabamento saudável e hidratado 🧴 INFORMAÇÕES DO PRODUTO Produto: Dr.Althea 345 Relief Serum Volume: 30ml Tipo: Sérum calmante Tipo de Pele: Todos os tipos de pele, especialmente pele sensível e desidratada 🫧 COMO USAR 1️⃣ Aplique após o tônico 2️⃣ Distribua uma quantidade adequada sobre o rosto 3️⃣ Espalhe suavemente e dê leves batidinhas até a absorção completa 4️⃣ Finalize com um hidratante 💡 Dica: Aplique uma camada extra nas áre