INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44303501719', 'FIltro Ar Condicionado CORSA 1999/2001 - 37085 - AKX3536', 'FIltro Ar Condicionado CORSA 1999/2001 (Classic / Hatch / Pick Up / Wagon / Milleniun / Sedã / Super / Wind) - Motor 1.0 16v Gasolina - (Mecânico) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 27.63, 27.63, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7raux-maou4y1eagaree', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F44303501719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393015705', 'Pneu Firestone Aro 15 F-600 195/55R15 85H', 'Marca: FIRESTONE Modelo: F-600 Medida: 195/55R15 Largura: 195 Perfil: 55 Tamanho de Aro: 15 Índice de peso: 85 - 515 kg, 85 Índice de velocidade: H - 210 km/h, H Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Assimétrico UTGQ: 200BB Adesão à àgua: E Eficiência energética: E Ruído externo: 72 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O pneu Firestone F600 é atualmente a melhor opção em custo x benefício da marca para carros pequenos e médios. Com ótimo escoamento de água, este modelo evacua e canaliza a água de forma eficiente, evitando aquaplanagens e garantindo a segurança em pista molhada. A banda de rodagem é assimétrica e conta com ombros largos e com pequenos cortes que reduzem o ruído, o que torna o Firestone F600 um pneu silencioso e confortável. A área central exerce amplo contato com a pista, o que melhora significativamente a aderência nas frenagens e mudanças de direção, mesmo em velocidades mais elevadas. Sua estrutura é reforçada e garante segurança contra impactos comuns como buracos e desníveis do asfalto. Além disso, é um pneu com a já reconhecida qualidade da marca Firestone, além de contar com selo do Inmetro e cinco anos de garantia. Sobre a marca Firestone A marca Firestone foi fundada em Ohio nos Estados Unidos, 1900. Há mais de um século os pneus Firestone equipam veículos com alta qualidade e segurança. A confiabilidade de utilizar um pneu bom, seguro e acessível, faz dos pneus Firestone uma ótima opção para o seu veículo, seja para lazer ou trabalho. Com diversas linhas disponíveis, sem dúvida uma delas vai atender à sua necessidade, com a garantia da experiência de uma marca tradicional no mercado de pneus e a garantia de utilizar o que há de melhor no desenvolvimento de pneus.', 476.34, 438.24, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Industrial Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwu-lxl7xxyldn7ua8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22393015705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
