INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799436699', 'Bolo Triplo Chocolate Ana Maria', 'Apresentamos o Bolo Ana Maria Triplo Chocolate, uma explosão de sabor para os amantes de chocolate! A combinação perfeita de chocolate ao leite, chocolate amargo e chocolate branco em cada mordida. Ideal para um lanche rápido ou para compartilhar com a família e amigos. Cada bolo é cuidadosamente embalado para manter sua frescura e sabor.', 4.99, 4.99, NULL, 'Food & Beverages > Bakery > Cakes & Pies', 'https://cf.shopee.com.br/file/sg-11134201-8261v-mj72olpnzeo615', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F23799436699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693508644', 'Flange Bomba Combustível Gm Celta 2005 a 2009 - 832370 - 2407', 'Flange Bomba Combustível Gm Celta 2005 a 2009 832370 2407 1.0 8v Flex Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 74.19, 74.19, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbkw-lmxwgnuy9sgb1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22693508644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493752163', 'Mangueira Radiador Superior I30 2.0 16v 2009 Ate 2016 - 90324 - 6003', 'Mangueira Radiador Superior I30 2.0 16v 2009 Ate 2016 2.0 16v - SuperiorO liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 96.21, 96.21, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-825af-mr215b2fk5j53c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22493752163', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397682428', 'Shampoo Anticaspa Clear Men Ice Cool Mentol 400ml', 'Shampoo Anticaspa Clear Men Ice Cool Menthol 400mL. Desenvolvido para homens. Porque o couro cabeludo do homem está mais propenso a caspa. Nova tecnologia Bio Booster com vitamina B3 e amino ácido. Ajuda a ativar as defesas naturais do couro cabeludo. Acaba com a caspa recorrente. Com mentol refrescante. Sensação de refrescância que dura o dia todo. Mentol é conhecido por seu efeito refrescante no couro cabeludo. Acaba com a caspa que insiste em voltar, além de proporcionar uma sensação intensa de refrescância e remoção da oleosidade. Recomendado para couro cabeludo oleoso e irritado. Quanto mais você se esforça, mais seu corpo irá protestar. O suor e a umidade em um dia intenso ou após a prática de esportes, podem deixar você com um couro cabeludo com coceira, o que possivelmente ajudará no aparecimento da caspa. Desenvolvido para homens, porque o couro cabeludo do homem está mais propenso a caspa o Shampoo CLEAR Men Ice Cool Menthol com Mentol, remove a sujeira, oleosidade e caspa no cabelo e couro cabeludo, enquanto proporciona uma explosão de refrescância incrível. Formulado com Bio-booster, a nova tecnologia inteligente de Clear que alia a expertise no cuidado com o couro cabeludo e a expertise no cuidado com a pele o novo CLEAR Men Ice Cool Sport Menthol Shampoo Anticaspa, ajuda a ativar a proteção natural do couro cabeludo e acaba com a caspa que insiste em voltar.', 44.69, 44.69, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rd3r-lvay54p3gaq889', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F21397682428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18205870342', 'Apoio de Braço Etios 2013 Até 2021 C/ Porta Objeto', 'Apoio de Braço Encosto, Descanso de Braço Etios 2013 Até 2021. O apoio de braço é um item automotivo que proporciona um conforto único ao motorista, é um acessório indispensável para viagens longas ou trânsitos intensos na cidade, deixa o interior do veiculo com uma aparência luxuosa e elegante, oferecendo um espaçoso porta objetos onde o(a) motorista pode armazenar itens como: carteira, celular, caneta, moedas, batons/maquiagens, entre outro objetos que normalmente ficam soltos pelo veículo. O Apoio de Braço NAT possui uma instalação simples e intuitiva, o motorista consegue realiza-la em sua própria residência, não sendo necessários furos ou colas para fixação. O produto é encaixado no console central do veículo e é confeccionado em plástico ABS de alta resistência com sua estrutura em aço carbono. Informações: * Para o Modelo Etios 2013 Até 2021. * Produto Nacional. * Braço articulado que permite flexibilidade na Regulagem. * Acabamento Sofisticado. * Acabamento Interno em Santoprene , evitando que objetos deslizem e façam barulho. * Instalação simples, rápida e intuitiva. * Não precisa realizar furos ou uso de colas, basta apenas encaixar no console central. * Revestimento em matéria ecológico de alta qualidade. * Juntas Articuladas. * Espaço Interno dividido em dois compartimentos e porta canetas. * Base em aço de carbono de alta qualidade e resistência. Veículos Compatíveis: * Modelo: Etios. * Ano: 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020 e 2021. Dados Técnicos: * Peso: 2,0 kg. * Altura: 31 cm. * Comprimento: 30 cm. * Largura: 12 cm. Cores Disponíveis: * Preto Com Linha Preta. * Cinza Com Linha Cinza. * Grafite Com Linha Grafite. * Preto Com Linha Branca. Conteúdo * 01 Apoio de braço. Garantia De Fabrica 3 meses * Imagens meramente ilustrativas. Atenção: Para compras realizadas em nome de Pessoa Jurídica/CNPJ, não serão faturadas, no momento não estamos gerando nota para CNPJ, caso tenha interesse em efetuar compras com o CNPJ entre em contato com a fábrica. Por favor solicitamos que compre como pessoa física/CPF para que seus pedidos possam seguir conforme o programado e prazo passado. Sobre a Marca: A Indústria NAT tem orgulho de ser uma empresa nacional, com sua sede em São Paulo, que está há mais de 20 anos construindo uma história de sucesso no âmbito do desenvolvimento de peças automotivas que acompanham e solucionam as necessidades de consumo do mercado, com o mais alto padrão de qualidade, proporcionando o melhor custo-benefício aos consumidores e sempre buscando ser referência em sua atuação. Seus produtos são produzidos em território nacional e estão presentes em toda América Latina.', 229.9, 179.33, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m285dtl4b8ba86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F660182224%2F18205870342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
