INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999134805', 'Kit Calota Original Hilux Tdi Diamond Srx 2018 2019 Aro 20', 'Produto: Calota Hilux Tdi Diamond Srx na cor Preto Brilhante com emblema Toyota Cromado em alto relevo Aplicação: Roda de Liga Leve Original De Fábrica aro 18 ano 2019 a 2020 ATENÇÃO: NÃO SERVE em rodas réplicas, somente em roda original de fábrica Valor referente a: 04 unidades (ao efetuar a compra coloque 01 na quantidade que se refere ao kit com 04 peças) Forma de fixação da peça: Encaixe Disponível em estoque: Sim Produto novo: Sim Material da calota: Plástico Abs Forma de envio: Mercado Envios - Os produtos são enviados pelo correio ou transportadora isso é definido pelo mercado envios de acordo com o CEP da sua região Temos loja física desde 1996 Antes de efetuar a compra, verifique todo o anúncio afim de adquirir corretamente o produto que precisa, e se o modelo anunciado é o mesmo da sua roda, caso não seja não garantimos compatibilidade, verifique também as medidas informadas nas fotos, cor e quantidade desejada e se seu endereço de envio esta correto, evitando assim aborrecimentos com sua compra Não aceitaremos devolução de produtos comprados para teste e não nos responsabilizamos por adaptações! Desde já agradecemos e ficamos a disposição para dúvidas através do campo de perguntas ou após a compra também há opção de envio de fotos através da opção mensagem ao vendedor para confirmação do produto adquirido', 219.85, 219.85, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Wheel Cover', 'https://cf.shopee.com.br/file/sg-11134201-821fs-mgidoxbj2q6h1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322429563%2F22999134805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
