INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999492913', 'Conjunto Blusão Cropped e Calça Infantil Menina Guloseima', 'Conjunto infantil para meninas, composto por um blusão cropped e uma calça, ambos confeccionados em moletinho leve. O blusão possui gola redonda, cava deslocada, estampa no peito com escrita e elástico na barra. A calça conta com elástico na cintura, que se ajusta conforme o corpo da criança, sem machucá-la, e com filetes laterais dispostos verticalmente, adicionando detalhes à peça e ao conjunto.Tecido: Blusão: Moletinho | Calça: MoletinhoComposição: BLUSÃO: 100% algodão | CALÇA: 100% algodãoModelagem: JustaComprimento Manga: LongaComprimento: LongoForro: NãoCintura: MédiaDecote/Gola: Redondo', 164.9, 49.47, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rat9-mau06hniu1ya44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F18999492913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
