INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493699090', 'Conjunto Infantil para Menino com Camiseta e Bermuda Up Baby', 'Conjunto infantil para menino, ideal para garantir conforto e estilo para os dias de brincadeira no verão. A camiseta é feita em meia malha flamê, possui uma estampa cheia de detalhes, bolso frontal com a escrita The Good Dudes, e gola em ribana, que deixa a peça mais confortável, sem agredir a pele do pequeno. A bermuda é feita em moletom sem felpa, e oferece conforto e flexibilidade para as atividades do dia a dia, com um ajuste seguro proporcionado pelo cós elástico e o cordão funcional. Além disso, possui bolsos funcionais e braguilha falsa, complementando o conjunto.Tecido: Camiseta: Meia Malha Flamê | Bermuda: Moletom Sem FelpaComposição: BERMUDA: 50% algodão 50% poliéster | CAMISETA: 100% algodãoModelagem: JustaComprimento Mangas: CurtaComprimento: CurtoForro: NãoCintura: MédiaDecote: Redondo', 214.9, 85.96, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rbna-m62p9doeukq3a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F23493699090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
