INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257458041', 'Gorro Rusty Byron', 'Gorro Rusty Byron Gorro Rusty Byron. Possui modelagem com vira e aplicação de etiqueta Rusty. Confeccionado em acrílico - 100% Acrílico - Modelagem com vira - Aplicação de etiqueta Rusty Sobre a marca Rusty Criada 1985 na Califórnia, Rusty Preinsedorfer começava sua própria linha de pranchas com o nome Rusty. Através de suas parcerias ficou conhecida mundialmente. Sua principal essência é poder viajar, criar, rir, ouvir música, e aproveitar a vida, cada um com seu estilo e o ambiente que os envolve. Com suas inovações Rusty passou a ser conhecida dentro e fora do surf, atingindo públicos como skatistas e simpatizantes. Produto Original.', 109.99, 88.0, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mm6k6a5rm1hg5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490043415%2F58257458041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
