INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493571505', 'Punho Interruptor de Partida P/ Suzuki Yes 125 2008-2010 Magnetron', 'Interruptor de Partida e Emergência O interruptor tem a função de informar o acionamento da buzina, embreagem, farol, freios, cavaletes, neutro, partida e pisca. Conteúdo da Embalagem: 01 Punho de Partida - Magnetron Código Original: 37200-28G20 Compatível com: SUZUKI EN 125 YES (2008-2010) EN 125 CARGO YES (2008-2010) Sua moto não está ligando porque o botão de partida parou de funcionar? Adquira Interruptor de partida e emergência feito no padrão original. Punho de partida, pronto para instalação, contendo o botão de partida e botão engine stop. Conta com proteção em todos os fios, auxiliando na proteção contra danos causados pela chuva e calor, proporcionando maior vida útil ao produto. Fabricado a partir do modelo original produzido com materiais de alta de qualidade e resistentes, garantindo maior durabilidade. Especificações Técnicas: - Padrão de Medidas OEM - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Confeccionado com a melhor matéria-prima - Material leve e resistente - Excelente qualidade e acabamento *Com esse botão de partida você garante longa vida útil sem perder as funções dos seus devidos acionamentos. Aproveite! Características: - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Testado e aprovado dentro das normas de segurança. Importante: - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo mau uso do produto.', 132.9, 119.61, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rfh4-m3gmqwm7cntib8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F23493571505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697297882', 'Maiô De Natação Infantil Helanca Com Detalhe Hammerhead', 'O Maiô Infantil Helanca Hammerhead oferece um misto de qualidade, conforto e beleza para as atividades aquáticas e/ou momentos de lazer de suas crianças. Suas alças cruzadas e sua combinação de cores tornam a peça ainda mais estilosa. Produzido com os melhores tecidos de helanca que garante durabilidade e elasticidade a peça. Indicado para: Atividades aquáticas Composição : 100% Poliamida Forro : 100% Poliamida Cuidados : Após o uso enxague seu traje em agua corrente fria e limpa. Deixar secar em local com temperatura ambiente. Não guardar ou deixar diretamente na luz do sol. Não esfregar ou lavar com produtos químicos. Guardar seu traje quando estiver totalmente seco. Conteúdo da Embalagem: 01 un. Maiô de Natação Infantil Helanca com Detalhe Hammerhead Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 93.8, 93.8, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/sg-11134201-7rble-lqm8k6pkjq1022', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F23697297882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
