INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594057667', 'Kit Colcha Solteiro Buddemeyer Hanna Jacquard 2 peças', 'CARACTERÍSTICA DO PRODUTO: Toque surpreendentemente macio com acabamento de excelente qualidade Elegantes florais e folhagens em jacquard Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 colcha 170x250cm + 1 porta travesseiro 50x70cm COMPOSIÇÃO: 52% Algodão 48% Poliéster- Enchimento 100% Poliester TIPO DE MATERIAL: 52% Algodão 48% Poliéster- Enchimento 100% Poliester DESCRIÇÃO: Kit Colcha Solteiro Hanna Jacquard. Com toque surpreendentemente macio, o Kit Colcha Hanna remete às experiências de puro conforto. Elegantes florais e folhagens em jacquard ornamentam o modelo com riqueza em detalhes, trazendo beleza e sofisticação. O modelo possui toque extremamente confortável, ideal para agregar charme à decoração e tornar a cama mais aconchegante. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lave antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 40°C. O melhor sabão para manter as características do produto é o de coco ou neutro. Não colocar sabão diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Não passar. Não usar ferro a vapor. Não lavar a seco.', 521.63, 410.42, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/sg-11134201-7ratl-mabl3ovrjlpuba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F22594057667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
