INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40625512961', 'Leâo Fases Xô Tpm Cer+Mor+Bau 10', 'A Leão lança uma linha focada no autocuidado feminino, entregando uma nova experiência de consumo para todas as fases da vida das mulheres. Ingredientes:Hibisco, Citrato de Magnésio, Melissia, Cacau, Sálvia, Aroma Natural de Morango, Estévia, Aroma Natural de Baunilha, Gluconato de Zinco, Aroma Natural de Cereja, Morango, Suco de Cereja em Grânulos. ALÉRGICO:Não contém glúten Conservar ao abrigo do Sol e Calor em local limpo, seco, arejado e sem odor. Produto sujeito a variação de suas características, devido à presença de ingredientes naturais. Utilize água filtrada. Consumir imediatamente após preparo ou guardar por no máximo 8 horas em recipiente limpo e sob refrigeração. Usar a quantidade indicada de água é importante para garantir uma melhor experiência.', 16.86, 14.33, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/sg-11134201-8258k-mg563fe16mfj4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F40625512961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
