INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092664657', 'Pré Treino Insane Original Com Beta Alanina 400g Sabor Fruit Punch - Demons Lab (Pre Workout Foco Intenso Performance Máxima)', 'COMPOSIÇÃO DO ANÚNCIO: 01 Pré Treino Insane Original 400g - Demons Lab INSANE ORIGINAL apresenta ingredientes poderosos de construção muscular (beta alanina e citrulina) em doses cientificamente validadas e comprovadas para construir mais músculos. Para aumentar a força e melhorar o desempenho na academia, os pesquisadores da Demons Lab incluíram uma dose inspirada em pesquisa de Beta-Alanina. Além disso, a dose precisa de Taurina encontrada em três Scoops foi mostrada em pesquisas científicas para aumentar o desempenho em atletas de resistência. BENEFÍCIOS: ✓ Aumenta a disposição; ✓ Resistência aprimorada; ✓ Máxima performance; ✓ Foco intenso. SUGESTÃO DE USO: Diluir 5g (1 scoop) em 200ml de água gelada e guardar em um recipiente bem fechado para consumir. INGREDIENTES: Beta Alanina, L-Arginina, Taurina, Bisglicinato de Magnésio, Colostro Bovino em Pó, Alga Chondrus Crispus Invernal (L-Citrulinilarginina), Taurina, Extrato de café verde, Cafeína, L-Tirosina, Cisteína, N-Acetil L-Metionina, Extrato de semente de uva, Ácido Ascórbico, Zindo Aspartato, Vitamina B6 (Cloridrato de Piridoxina), Acidulante ácido Cítrico, Aroma Idêntico ao Natural de Frutas Vermelhas, Corante Beterraba e Edulcorante Sucralose. ALÉRGICOS: PODE CONTER AMENDOIM, LEITE, SOJE E OVO. NÃO CONTÉM GLÚTEN. COMTÉM LACTOSE. IMAGEM MERAMENTE ILUSTRATIVA TABELA PODE VARIAR CONFORME SABOR', 194.46, 149.7, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-loek30ouz6137f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F418949963%2F22092664657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
