INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292996736', 'Gabinete Suspenso para Banheiro 80cm 1 Porta Basculante 1 Nicho Laranja/Amendoa Amêndoa', 'Quando falamos de banheiro pensamos em bem-estar. Pois o banheiro é onde a gente recarrega nossa energia vital, idealiza sonhos, e realiza toda a manutenção necessária para uma saúde física e mental. Com design prático, o móvel entrega ao ambiente toques de modernidade e elegância. Funcional, acondiciona produtos de higiene e beleza, porta escova, papel higiênico, toalhas, artigos de limpeza, entre tantos outros objetos pessoais. Balcão Gabinete Suspenso para Banheiro BN3601. Possui porta articulável e um nicho lateral. Estrutura em MDP e acabamento em BP. Não acompanha cuba. Imagem meramente ilustrativa. A decoração do ambiente não acompanha o produto. Produto novo, acompanha nota fiscal. O produto será entregue desmontado. Estilo: Moderno Peso (kg): 10.8 Garantia: 03 Meses Altura (cm): 26.5 Acabamento: BP Melamínico Largura (cm): 80 Possui Pés: Não Possui Sifão: Não Possui Tampo: Sim Possui Nichos: 1 Possui Portas: Sim Tipo de Porta: Basculante Acompanha Cuba: Não Possui Gavetas: Não Suporta Até (kg): 10 Profundidade (cm): 38.7 Escala de Brilho: Semi-Brilho Tipo de Gabinete: Gabinete Aéreo Material da Porta: MDP Material do Tampo: MDP Origem do Produto: Nacional Ambiente Principal: Banheiro Material Principal: MDP Necessita Montagem: Sim Possui Prateleiras: Não Acabamento da Porta: BP Melamínico Tamanho do Gabinete: Médio: de 60cm a 80cm de largura Suporte para Toalheiro: Não Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Tipo de Puxador da Porta: Não Possui Escala de Brilho da Porta: Super Brilho Tipo de Móvel para o Banheiro: Gabinete de Banheiro Possui Recorte No Tampo Para Cuba: Não Tipo de