INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593513225', 'Armário para Cozinha Torre Forno e Microondas 100% MDF Bege/Freijó/Branco', 'Torre Quente 2 Portas A Torre Quente 2 Portas é fabricada em 100% MDF com pintura UV, garantindo alta durabilidade e resistência. Além de um design moderno, oferece compartimentos bem distribuídos e espaço dedicado para forno e micro-ondas. Os pés são reguláveis, e os puxadores em ABS proporcionam um excelente acabamento. A Torre possui espaço para dois fornos o que possibilitam a versatilidade do móvel tornando-o mais espaçoso, conferindo praticidade e usabilidade no dia a dia. Estilo: Clássico Modular: Sim Peso (kg): 27.6 Garantia: 03 Meses Altura (cm): 200 Acabamento: Pintura UV Largura (cm): 60 Possui Pés: Sim Possui Vidro: Não Possui Portas: Sim Tipo de Porta: Bater Altura dos Pés: 17 Pés Reguláveis: Sim Possui Gavetas: Não Possui Rodízio: Não Suporta Até (kg): 25 Acompanha Tampo: Não Possui Espelhos: Não Profundidade (cm): 52 Escala de Brilho: Brilhante Material dos Pés: ABS Material da Porta: MDF Origem do Produto: Nacional Acabamento dos Pés: Pintura Ambiente Principal: Cozinha Material Principal: MDF Necessita Montagem: Sim Possui Prateleiras: Não Acabamento da Porta: Pintura UV Sapatas Niveladoras: Não Balcão Acompanha Pia: Não Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Tipo de Puxador da Porta: Externo Escala de Brilho da Porta: Brilhante Espessura da Estrutura (mm): 12 Tipo de Armário de Cozinha: Paneleiro Acompanha Rodapé Decorativo: Não Material do Puxador da Porta: ABS Informações Complementares (Novo): Armário Para Cozinha Torre Forno e Microondas 100% MDF Tipo de Dobradiça/Corrediça da Porta: Simples Material da Dobradiça/Corrediça da Porta: Metálica Marca: Genialflex Cor Flex: Não Cor Interna: Branco Cor do Produto: Freijó/Branco Itens In