INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27243764189', 'Camisa Corinthians Gold Elegância do Timão Masculina', 'A Camisa Corinthians Gold eleva o preto e dourado a outro nível. Inspirada na estética de luxo do esporte moderno, ela traz o escudo do Timão em detalhe dourado em alto relevo — um símbolo de força, tradição e respeito. Com corte moderno, gola V estilizada e acabamentos dourados nas mangas e laterais, esta peça entrega presença antes mesmo de entrar em campo. É o tipo de camisa que fala sozinha: classe, personalidade e Corinthians. Perfeita para o lifestyle urbano, ela combina com looks casuais, streetwear ou produções mais elegantes. Uma peça feita para o torcedor que sabe que vestir o Timão é mais do que futebol — é identidade. Benefícios: - Feita pro Torcedor Raiz: preto e dourado que impõem respeito. - Escudo Dourado Premium: acabamento de alto nível, com presença e brilho na medida. - Estilo de Jogo: gola V moderna e recortes que valorizam o shape. - Conforto Máximo: tecido leve, respirável e de toque macio. - Lança o Lifestyle Corinthiano: combina com qualquer outfit urbano.', 189.9, 170.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/br-11134207-81zuj-mkmim08ej30j17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F698219490%2F27243764189', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
