INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49511151885', '(New Arrival) Lovito Vestido Casual com Bolso e Padrão de Botão para a Primavera/verão Amarelo para mulheres L196ED659', '✅DESTAQUES -❤️Bolso -❤️Botão -❤️Padrão -❤️Macio e confortável -❤️Primavera e verão -❤️Embelezado com botão -❤️Fim de semana casual ✅DESCRIÇÕES Estampa / Padrão:Listra Estilo:Casual Tipo de vestido:A Line Tamanho Plus:No Material:Poliéster Composição:100%Polyester Tipo de modelagem:Regular Fit Transparência:No Esticar:Non-stretch Feito na China ✅O PACOTE INCLUI 1XVestir ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 67.0, 46.5, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-823qn-mpc7lzjg64g087', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F49511151885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
