INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794083423', 'Kit 2 Pneus 215/75R16 C 8 Lonas 113/111R Forza Van F1 Xbri', 'Pneu XBRI Forza Van F1 – Resistência e Desempenho para Vans e Veículos Utilitários O XBRI Forza Van F1 foi desenvolvido especialmente para vans e veículos utilitários, garantindo durabilidade, segurança e alta performance em trajetos urbanos e rodoviários. Com um design robusto e composto reforçado, proporciona maior estabilidade, excelente aderência e resistência ao desgaste, sendo ideal para quem busca um pneu confiável para o transporte de passageiros e cargas. Principais Benefícios do XBRI Forza Van F1: Alta resistência ao desgaste – Composto especial que prolonga a vida útil do pneu. Ótima capacidade de carga – Estrutura reforçada para suportar o peso extra de vans e utilitários. Aderência e estabilidade – Excelente tração em superfícies secas e molhadas, garantindo mais segurança. Conforto na condução – Rodagem silenciosa e suave, reduzindo ruídos e vibrações. Eficiência no consumo de combustível – Baixa resistência ao rolamento para maior economia. O XBRI Forza Van F1 é a escolha ideal para quem busca desempenho, segurança e durabilidade em um pneu projetado para vans e utilitários. Kit 2 Pneus 215/75R16 C 8 Lonas 113/111R Forza Van F1 Xbri Marca: Xbri Modelo: Forza Van F1 Aro: 16 Índice de peso (por pneu): 113 - 1150kg Índice de peso (rodado duplo): 111 - 1090kg Índice de velocidade: R - 170km/h Construção: Radial Tipo: Uso sem câmara Aplicação: Vias pavimentadas Tipo de desenho: Simétrico Lateral: Letras pretas Garanta já o seu e tenha mais eficiência e tranquilidade no dia a dia.', 1191.36, 1144.36, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rau5-mass6q027wi829', 'https://shope.ee/an_redir?origin_link=h