INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251535068', 'Tamanco Feminino Flat Modare 7217100', 'O Tamanco Feminino Flat Modare 7217100 é perfeito para se manter confortável e estilosa nos dias mais quentes. Seu design moderno e elegante, aliado à sua leveza, garante total versatilidade para compor diferentes looks. Além disso, possui um solado resistente e macio, proporcionando maior aderência e conforto ao caminhar. Ideal para quem busca praticidade e conforto sem abrir mão do estilo. . MODELO: B0447217 REFERENCIA: 7217100 MARCA: Modare MATERIAL DA PALMILHA: Ultracomfy- Palmilha ultramacia que acomoda o pé de forma anatômica. MATERIAL DA SOLA: Borracha ACABAMENTO: Colado/Costurado GÊNERO: Female GRUPO DE IDADE: Adult TIPO DE SALTO: Flat MATERIAL DO SAPATO: Napa Floather Nature MEDIDA DO SALTO: 2,5 cm aproximadamente ESTILO: Salto baixo TIPO: TAMANCO', 118.99, 118.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-822zo-mhw0nlufa9zaca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F58251535068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
