INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792500688', 'Fantasia Mumia Halloween Infantil Longa Com Mascara e Luva', 'Itens inclusos na fantasia 1 fantasia Mumia Infantil de Halloween 1 máscara de Halloween 1 par de luvas de Halloween Tamanhos: P - Numeração de roupa 2 a 4. M - Numeração de roupa 5 a 8. G - Numeração de roupa 9 a 10. GG - Numeração de roupa 11 a 12.. Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. E por ser para criança, a fantasia irá durar por mais tempo conforme ela for crescendo. Especificações Técnicas Material: Fantasia 100% poliéster. Produto: Fantasia nova e na embalagem. Fantasia a pronta entrega! Prepare-se para uma noite de sustos e diversão com esta incrível fantasia de múmia! Nosso macacão é projetado com estampas que simulam as faixas de uma múmia antiga. Acompanha uma máscara estampada com uma boca de zumbi e uma cicatriz na testa, criando uma aparência verdadeiramente aterrorizante. As luvas também possuem estampas que imitam as faixas de múmia, completando o visual. Com Luvas Com Máscara Assustadora Modelo Longo Não pinica Não esquenta Secagem rápida Leve e confortável', 193.59, 193.59, NULL, 'Baby & Kids Fashion > Boy Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-7rblr-lmhtw2xe44t53b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F23792500688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898994806', 'Roupa de Policial Infantil Masculina Longa Swat', 'Itens inclusos na fantasia de Policial Swat: 01 Macacão Estampado Tamanhos: P - Numeração de roupa 2 a 4, para crianças que tenham até 99 cm de altura, dos pés a cabeça. M - Numeração de roupa 5 a 8, para crianças que tenham de 100 a 119 cm de altura, dos pés a cabeça. G - Numeração de roupa 9 a 12, para crianças que tenham de 120 a 140 cm de altura, dos pés a cabeça. Especificações Técnicas Material: Fantasia 100% poliéster exceto adornos. Produto: Fantasia nova, na embalagem. Cor: Azul O seu pequeno quer ser policial quando crescer? Garanta a diversão do seu pequeno com essa linda fantasia de Policial Infantil da Swat! A roupa de policial infantil masculina é composta por uma lindo macacão longo com estampa super detalhada e realista, possui estampa do colete de balas, de coldre na altura da coxa e brasão da policia nos braços, com pequena abertura na região das costas e cordões para amarrar que facilitam na hora de vestir a roupa. A fantasia é produzida em material de excelente qualidade e super confortável. Aproveite! Temática Policia Swat 100% Poliéster Não esquenta Não Pinica', 74.9, 74.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-824in-melg4zib8xs242', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F19898994806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
