INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399253746', 'Vara Black Tamba Pro Carretilha Maruri 2,40m 60lb 2 Partes', 'Vara Black Tamba Pro Carretilha Maruri 2,40m 60lb 2 Partes A vara de pesca BLACK TAMBA PRO é uma escolha excepcional para pescadores que buscam qualidade e desempenho superiores. Com um design sofisticado e detalhes dourados, esta vara oferece não apenas funcionalidade, mas também elegância e estilo à sua experiência de pesca. Construída com um blank de carbono IM8, esta vara combina leveza, resistência e força, proporcionando uma resposta rápida às fisgadas, essencial para lidar com peixes de grande porte. Fabricante: Maruri Modelo: Black Tamba BTPRO-C802 Utilização: Carretilha Tamanho: 8''0" - 2,40m Libragens: 30 – 60Lb Ação: Extra Rapida Secção: 02 Partes Tamanho total do cabo: 48 cm Reel Seat em Black Piano 7 passadores + ponteira. Material do passador e ponteira: Óxido de Alumínio Material do cabo: E.V.A - Bipartido Fore Grip em E.V.A. Blank: Carbono Tubular IM8 Peso Aproximado: 196g', 456.0, 397.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rd3w-lus3vvr85m93bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F19399253746', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193070328', 'Máquina de Corte Pro 300 – Lizz Pro', 'A Pro 300 da Lizz Pro entrega desempenho, precisão e resistência para quem busca resultados profissionais em cada corte. Equipada com motor potente e lâminas de aço inoxidável, ela oferece cortes rápidos, limpos e uniformes, mesmo nos cabelos mais grossos. Seu design ergonômico e moderno proporciona conforto e firmeza durante o uso, enquanto o sistema de ajuste de altura permite total controle do estilo desejado. Destaques do produto: Motor profissional de alto desempenho – potência constante e silenciosa Lâminas de aço inoxidável – afiação duradoura e cortes precisos Ajuste de altura de corte – versatilidade para diferentes acabamentos Uso com fio – energia contínua e sem perda de potência Construção robusta e ergonômica – conforto e durabilidade Perfeita para barbeiros, cabeleireiros e para quem gosta de cuidar do visual em casa, a Lizz Pro 300 une qualidade profissional, potência e praticidade em um só aparelho. Características e Especificações técnicas: • Tensão disponível: 127V ou 220V • Frequência: 50/60 Hz • Dimensões do produto: L: 6 cm C: 4 cm A: 21 cm • Peso: 300 g', 179.9, 99.0, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-821dh-mgp7c3zeyj9r4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1180886499%2F23193070328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999362622', 'Lençol de Elástico 200 Fios Vida Bela Kacyumara Branco', 'A linha Vida Bela é a combinação perfeita entre conforto e qualidade. Confeccionado em tecido 200 fios, o lençol com elástico proporciona uma sensação suave ao toque, ideal para quem busca uma experiência de descanso confortável e agradável. O algodão egípcio, reconhecido por sua durabilidade e maciez, garante resistência ao uso diário e ajuda a manter o visual elegante do quarto por muito mais tempo. O tecido oferece excelente conforto e acabamento refinado, tornando a experiência de descanso ainda mais aconchegante. Características Lençol com Elástico Solteiro: 0,90 x 1,90 x 0,30 m Solteiro Plus: 0,98 x 2,03 x 0,40 m Solteiro 1,20: 1,20 x 2,03 x 0,40 m Casal: 1,40 x 1,90 x 0,30 m Queen: 1,60 x 2,00 x 0,40 m King: 1,93 x 2,03 x 0,40 m Composição 100% Algodão Egípcio Percal 200 fios Diferenciais Ajuste Perfeito Modelagem com elástico que se adapta ao colchão, proporcionando melhor fixação e praticidade no uso diário. Antipilling Tecido com maior durabilidade e sem formação de bolinhas. Coordenado Coordena com edredom e cobre-leito da linha. Vendidos separadamente. Lavagem Siga as instruções de lavagem dispostas na etiqueta do produto. Atenção As cores do produto podem apresentar variações sutis de acordo com o lote de fabricação e/ou configurações de tela.', 199.9, 199.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-8261c-mlhu0lzdo075a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F23999362622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43472553735', 'Jogo de Ferramentas 11 Peças com Estojo de Cinto – Titanium Platina Profissional em Aço Carbono', 'O Jogo de Ferramentas com 11 Peças – Titanium Platina é o kit perfeito para quem busca praticidade, resistência e organização no dia a dia. Produzido em aço carbono de alta durabilidade com acabamento Titanium Platina, oferece desempenho profissional tanto para reparos domésticos quanto para uso técnico e industrial. Acompanha bolsa de nylon reforçada com encaixe para cinto, que facilita o transporte e mantém todas as ferramentas sempre organizadas e ao alcance das mãos. Ideal para eletricistas, mecânicos, montadores, marceneiros e também para quem gosta de realizar projetos DIY (faça você mesmo) com eficiência e segurança. ⚙️ Características Principais: 5 Chaves Allen: 2 mm, 2,5 mm, 3 mm, 4 mm e 6 mm 1 Trena: 1 metro 1 Chave Teste: para verificação elétrica de baixa tensão 1 Estilete: com lâmina retrátil para cortes precisos 1 Alicate Universal: 6" de alta resistência 1 Chave Phillips e 1 Chave de Fenda: tamanhos padrão Material: Aço carbono com acabamento Titanium Platina Bolsa de Nylon: resistente, com suporte para cinto (inclusa grátis) 🔩 Aplicações: Reparos residenciais e montagem de móveis Manutenção automotiva básica Instalações elétricas e verificações de tensão Trabalhos em marcenaria e bricolagem Projetos DIY e pequenos consertos profissionais 🌟 Diferenciais e Benefícios: Acabamento Titanium Platina: proteção extra contra corrosão e desgaste Conjunto Completo 11 Peças: ferramentas essenciais em um só kit Alta Resistência: aço carbono de longa durabilidade Transporte Prático: bolsa de nylon com suporte para cinto Ergonomia e Conforto: design pensado para uso prolongado sem fadiga 📋 Informações Técnicas: Material: Aço carbono com acabamento Titanium Platina Chaves Allen: 2 mm, 2,5 mm, 3 mm, 4 mm, 6 mm Trena: 1 metro Chave Teste: baixa tensão Estilete: lâmina retrátil Alicate Universal: 6" Chave Phillips / Fenda: tamanho padrão Bolsa: nylon resistente Medidas da embalagem: 13,5 cm (C) x 13,5 cm (L) x 4 cm (A) Peso Bruto: 0,388 kg Código de Barras: 7908200008488 💡 Resumo: O Jogo de Ferramentas 11 Peças Titanium Platina oferece qualidade, praticidade e durabilidade em um kit compacto. Seja para reparos rápidos ou trabalhos profissionais, é a escolha certa para quem busca desempenho e organização em um único produto! 📍 Como Calcular seu Frete Trabalhamos com cálculo de frete automático gerado junto à plataforma. Basta procurar na página do anúncio a opção de cálculo e inserir o seu CEP para obter o valor exato. ❓ Dúvidas Frequentes O produto é novo? Sim, o produto anunciado é novo. O produto está disponível em estoque? Sim, disponível para envio imediato após a liberação da compra. O produto acompanha nota fiscal? Sim. Ela estará disponível no campo de mensagens assim que for emitida. Qual o tempo de envio e formas de entrega? Pedidos liberados até às 13h são despachados no mesmo dia; após esse horário, no próximo dia útil. Como são realizadas as entregas? Via Correios ou Transportadoras. Todos os itens das fotos acompanham o produto? Apenas os descritos no anúncio. Algumas imagens são ilustrativas. Você ainda tem dúvidas? Use o campo de perguntas que responderemos rapidamente. 🔸 Somente clique em comprar após ter certeza de honrar a compra e concordar com as condições descritas.', 39.99, 37.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfb7dssdfbb983', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226987671%2F43472553735', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41810682397', 'PANIC PRE-TREINO 300G PONCHE DE FRUTAS ADAPTOGEN', 'Experimente o Panic Pré Treino 300g da Adaptogen Science, um suplemento inovador que potencializa seu desempenho e resistência durante seus treinos. Com um sabor delicioso de suco de frutas vermelhas, esse pó é fácil de misturar e proporciona uma explosão de energia que você vai adorar. Cada porção de 10 g contém ingredientes poderosos como beta-alanina, cafeína, arginina e taurina, formulados para oferecer foco, agilidade e resistência. Ideal para pessoas a partir dos 18 anos, este suplemento é livre de glúten e não contém derivados do leite ou soja, tornando-se uma opção acessível para diversos estilos de vida. Com 30 porções por embalagem, você terá energia suficiente para dominar sua rotina de exercícios. Acompanhe seu progresso e supere seus limites com o Panic, o pré-treino que faz a diferença.', 250.0, 78.0, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mcqs3lr4080j08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965164614%2F41810682397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
