INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207379548', 'Capa case capinha para Xiaomi Redmi 13C 5G - Dual Shock X - Gshield', 'Eleve a proteção do seu Xiaomi Redmi 13C 5G a um patamar superior com a Capa Dual Shock X da Gshield. Proteção Dupla e Avançada A capa Dual Shock X é projetada com um compromisso inabalável com a segurança do seu aparelho. Não contentes com uma única camada de proteção, incorporamos duas para garantir que seu Xiaomi Redmi 13C 5G esteja duplamente protegido. Material de Alta Densidade que Não Amarela A capa é fabricada com polipropileno de alta densidade, que proporciona uma capacidade de resistir ao amarelamento com o tempo, mantendo a aparência do seu dispositivo. Proteção Elevada para a Câmera Entendemos o valor da sua câmera, e é por isso que a Dual Shock X apresenta uma elevação estratégica na parte traseira. Essa característica inteligente impede que a câmera do seu smartphone entre em contato direto com impactos e quedas inesperadas. ESPECIFICAÇÕES Material: Polipropileno de alta densidade - Não Amarela Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos à traseira Certificações: Us Military', 32.97, 32.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-8260a-mm490b3xvu9vbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F58207379548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598388414', 'Película Gshield Garmin Enduro 3 - Hydrogel HD, Ajuste Perfeito, Anti Marcas', 'A Película de Hydrogel da Gshield oferece proteção avançada para a tela do seu smartwatch, garantindo uma experiência duradoura e sem preocupações. Com tecnologia inovadora de hidro nano PET e TPU Soft Gel, essa película protege contra riscos indesejados. O revestimento oleofóbico não só aprimora a resistência a arranhões, mas também minimiza marcas de digitais, proporcionando uma visualização sempre clara e nítida. A película se ajusta perfeitamente às extremidades curvas do seu dispositivo, assegurando uma cobertura total sem comprometer a estética e a funcionalidade. Optar pela Película de Hydrogel Gshield é escolher um escudo sofisticado que combina tecnologia de ponta e durabilidade, mantendo a tela do seu relógio sempre impecável. Cuide do seu smartwatch com estilo e confiança, escolhendo a excelência em proteção que só a Gshield oferece. ESPECIFICAÇÕES Material: Hidro nano pet + TPU Soft Gel Marca: Gshield Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High Definition Certificações: US Military Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. COMPATIBILIDADE Garmin Enduro 3 ITENS INCLUSOS 1x Película protetora 1x Kit de Instalação GARANTIA 3 meses contra defeitos de fabricação', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rep1-m866m9i9f53ld5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22598388414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14394323512', 'Película Hydrogel para Moto G32 - Anti-Risco e Transparente - Gshield', 'Aumente a resistência com a película para Motorola Moto G32 A Película Traseira de Hydrogel para Motorola Moto G32, da Gshield, protege seu aparelho contra riscos e arranhões na parte de trás. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, a película se adapta às extremidades curvadas, cobrindo toda a traseira. Ideal para os adeptos ao uso do aparelho sem uso de capa, mas para uma maior proteção, as películas traseiras também podem ser usadas em conjunto com as capas da Gshield. ESPECIFICAÇÕES Material: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d ) Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à traseira Grau de transparência: 97% High Definition Certificações: US Military Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. COMPATIBILIDADE Motorola Moto G32 ITENS INCLUSOS 1x películas de hydrogel Kit de instalação', 38.47, 38.47, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-22100-antq7q9lv4ivcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F14394323512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
