INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202128096', 'Kit 4 Unidades Car Lub Desengripante Spray 300ml - Lubrificante Antiferrugem Multiuso Ação Rápida', 'Desengripante Spray Car Lub Car 80 – Solta, Lubrifica e Protege Pare de perder tempo com peças travadas e barulhos irritantes. O Car Lub Car 80 é um desengripante multiuso de alta eficiência que solta, lubrifica e protege em segundos, garantindo praticidade e resultados duradouros para uso automotivo, profissional ou doméstico. APLICAÇÃO / COMPATIBILIDADE Indicado para: - Porcas, parafusos e peças enferrujadas - Dobradiças, fechaduras e trilhos - Correntes (bicicletas, motos e equipamentos) - Ferramentas manuais e elétricas - Componentes automotivos em geral - Equipamentos domésticos, jardinagem e pesca DADOS TÉCNICOS Tipo: Desengripante multiuso em spray Marca: Car 80 Ação: desengripa, lubrifica e protege Alta penetração: alcança áreas de difícil acesso Lubrificação: reduz atrito e elimina ruídos Proteção: ação antiferrugem e anticorrosiva Aplicação prática em aerossol QUALIDADE E CERTIFICAÇÕES Produto desenvolvido com padrão profissional, amplamente utilizado em oficinas e manutenção em geral. A Car 80 é reconhecida pela qualidade e eficiência de seus produtos, garantindo desempenho confiável e durabilidade. RECOMENDAÇÕES IMPORTANTES Solta rápido: penetra profundamente e destrava peças sem esforço Não deixa sujeira excessiva: lubrificação eficiente sem acúmulo pesado Elimina rangidos: ação imediata contra ruídos Protege contra ferrugem: cria barreira contra umidade Multiuso real: um único produto para diversas aplicações Fácil aplicação: spray prático, ideal para locais de difícil acesso Agite antes de usar Aplicar diretamente na área desejada Reaplicar se necessário para máxima eficiência', 56.99, 56.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-81zu5-midpl1omajnnd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1424408486%2F58202128096', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
