INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49753307757', 'Pimenta Jamaica Siria Moida', 'Condimento aromático e versátil, com sabor que lembra uma combinação de canela, cravo e noz-moscada. Ideal para temperar carnes, aves, molhos, doces e preparos natalinos, trazendo um toque exótico e perfumado às receitas. Ingredientes: Pimenta Jamaica. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 34.22, 34.22, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mieo41uorl6q9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F49753307757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18317822727', 'Encordoamento Ernie Ball Baixo 4 Cordas 045 SuperSlinky 2834', 'Olá, seja bem-vindo à HGZ Music Store Está em busca de um encordoamento para Baixo Elétrico 0.045, para seu tão amado instrumento? A HGZ Music Store traz o Encordoamento Ernie Ball Super Slinky 4 Cordas para atender sua necessidade! As cordas Regular Slinky da Ernie Ball são as campeãs de vendas e utilizadas por muitos músicos de mundo inteiro. Os encordoamentos Ernie Ball passam por um processo de fabricação com os mais rigorosos e exigentes padrões e especificações disponíveis no mercado, garantindo o desempenho ideal, consistência e durabilidade. Encordoamentos Originais adquiridos pela importadora oficial da Ernie Ball no Brasil, Izzo Instrumentos Musicais. Tipos de Instrumento onde se pode utilizar: Baixo Elétrico de 4 Cordas Calibre da Cordas (Bitola/Espessura): 1 - Mi .045 2 - Si .065 3 - Sol .080 4 - Ré .100 Características do Produto: Materiais: Aço Carbono Temperado e Estanhado, Aço Niquelado, Níquel e Aço Cor: Prateada O que você está comprando: 1 Encordoamento para Baixo 4 Cordas Super Slinky Ernie Ball 0.045 P02834 Somos a HGZ Music Store, uma empresa totalmente focada em e-commerce no ramo de Instrumentos Musicais, sempre oferecendo as melhores marcas de equipamentos do mercado e com a devida expertise ao implementa-los ao nosso catálogo. Sua experiência será a de uma compra segura e garantida pelas melhores tecnologias de operação do mercado e entrega rápida! Caso tenha ficado alguma dúvida, nossa equipe estará pronta para te atender! HGZ Music Store', 239.9, 239.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7qvey-lgkwuuosrlite0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2