INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794939238', 'Gelatina Capilar Kolene Modeladora Superfinalizadores Rosa 1Kg', 'Características do Produto: Marca: Kolene Conteúdo: 1 Kg Tipo de Cabelo: Ondulados, Cacheados e Crespo Ean: 7908324409550 Características Adicionais: Ultra definição Brilho intenso Ação day after Não deixa resíduos Ação antirressecamento Não resseca Sem álcool (0%) Ideal para misturinhas 72h de definição Com Óleo de Rícino e Babosa Modo de Uso: Com os cabelos limpos e úmidos, aplique a Gelatina Capilar Kolene Ultra definição em uma quantidade equivalente a uma moeda por mecha, mecha a mecha, por toda a extensão dos cabelos. Desembarace os fios com um pente ou escova e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Você pode misturar a Gelatina Ultra definição com os demais finalizadores das Linhas Kolene, para obter uma finalização ainda mais poderosa. Para isso, adicione um pouco da Gelatina Ultra definição e do outro finalizador Kolene na palma da mão, esfregando para misturar os produtos. Aplique imediatamente a misturinha no cabelo, mecha a mecha, e amasse. Fornecedor: Flora - Cabelo', 39.81, 39.81, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-824gt-mpiadlfslf5t19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23794939238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
