INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43151849267', 'Kit Sensor Abs Xre 300 2019-2023 Dianteiro e Traseiro Magnetron', 'Kit Sensores de Abs Magnetron Compatível com: HONDA: XRE 300 2019 XRE 300 2020 XRE 300 2021 XRE 300 2022 XRE 300 2023 Conteúdo da Embalagem: 01 Sensor de Abs (Roda Dianteira) Magnetron 01 Sensor de Abs (Roda Traseira) Magnetron Código Original (OEM) Honda do Sensor Traseiro: 38510-KWT-FB1 Código Original (OEM) Honda do Sensor Dianteiro: 38520-KWT-FB1 Funções do Sensor Abs: Detecção da velocidade da roda: O sensor detecta a velocidade de cada roda, transmitindo essa informação para o módulo ABS. Evitar o travamento: Se o sensor detectar que uma roda está prestes a travar, o módulo ABS ajusta a pressão do freio, permitindo que o motociclista mantenha o controle da direção. Melhora a segurança: O sistema ABS aumenta a estabilidade da moto em situações de frenagem brusca, reduzindo o risco de derrapagem e colisão. Importância do Sensor: Manter o controle direcional: O sensor ABS permite que o motociclista mantenha o controle da direção, mesmo em situações de frenagem forte, evitando o travamento das rodas. Aumentar a segurança: A segurança da moto é significativamente aumentada pela presença do sensor ABS, especialmente em situações de frenagem de emergência. Especificações Técnicas: - Padrão de Medidas OEM - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Material leve e resistente - Excelente qualidade e acabamento Instalação: - Este produto possuí fácil instalação, não exige que mude a estrutura de sua moto, pois foi confeccionado seguindo as especificações do produto original, para encaixe e funcionamento perfeito. Importante !! - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo uso indevido do produto.', 219.9, 186.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rau1-ma2uuu23bvq407', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F43151849267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
