INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798203438', 'Suporte de telefone recarregável 2 em 1 para carro -J8', '🔋 Carregador Sem Fio Rápido 15W Universal - Tecnologia Qi ⚠️ ATENÇÃO: Seu celular PRECISA ter carregamento por indução (padrão Qi) para funcionar! ⚡ CARREGAMENTO SEM FIOS PRÁTICO E RÁPIDO ✅ 15W Máximos - Carrega tão rápido quanto um carregador com fio ✅ Universal - Compatível com todos celulares Qi (iPhone 8+, Samsung Galaxy S6+, etc) ✅ Design ultrafino - Não ocupa espaço e combina com qualquer ambiente 🎯 PRINCIPAIS BENEFÍCIOS: • Basta colocar o celular em cima para começar a carregar • Detecção automática - ajusta a potência conforme o aparelho • Funciona até com capas finas (até 8mm de distância) • Segurança total: proteção contra superaquecimento e sobrecarga 📦 CONTEÚDO: 1x Base de Carregamento Sem Fio 1x Cabo USB (adaptador vendido separadamente) 🔌 ESPECIFICAÇÕES: • Entrada: 5V/2A ou 9V/2A • Saída Ajustável: 5W/7.5W/10W/15W • Material: Superfície antiderrapante em silicone 📱 COMPATIBILIDADE: ✔ iPhone 8/8 Plus, X, XR, XS, 11, 12, 13, 14, 15 ✔ Samsung Galaxy S6/S7/S8/S9/S10/S20/S21/S22/S23, Note 5/8/9/10/20 ✔ Outros aparelhos com tecnologia Qi ❗ IMPORTANTE: • Não funciona com celulares sem Qi (verifique seu modelo antes) • Cores enviadas aleatoriamente (preto/branco) • Não inclui adaptador de parede 🎁 OFERTA ESPECIAL: 🚀 Frete Rápido | 💯 Garantia de 7 Dias 👉 PERGUNTE ANTES DE COMPRAR SE SEU CELULAR É COMPATÍVEL! 🔍 PALAVRAS-CHAVE (SEO Shopee BR): #CarregadorSemFio #CarregadorQi #TecnologiaWireless #CarregamentoRapido #AcessorioCelular #GadgetTecnologico #PresenteInteligente', 100.0, 55.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Measurement', 'https://cf.shopee.com.br/file/br-11134207-820mh-mn2b8yqmpudd48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fp