INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098203557', 'Teclado para Notebook Hp Mini 1104TU', 'Teclado compatível com Hp Mini 1104TU O teclado compatível com Hp Mini 1104TU foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Hp. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: 1104TU Moldura: Não se aplica Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC103-HP-0059 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: 1104TU, 1000, 1125NR, 1100, 496688-001, 1103TU, 1190BR, 496688-201, 1152NR, 1120BR, 1020LA, 1100CM, 1001TU, 1001XX, 1002TU, 1002XX, 1003TU, 1004TU, 1005TU, 1006TU Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 77.43, 77.43, NULL, 'Computers & Accessories > Peripherals & Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mqsoczr2d05q0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097013207%2F23098203557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992246009', 'Caneca Mosquetão Batman - DC', 'Depois de passar o dia salvando o mundo, você precisa de uma caneca que te salve da sede? A gente te ajuda! Com uma alça feita em mosquetão, para você pendurar na sua mochila enquanto pula compromisso e compromisso pela sua rotina! Não importa qual é a sua aventura, essa caneca te acompanha em todos os lugares! O produto é importado, feito em aço inoxidável, possui detalhes incríveis que vão fazer você se apaixonar! Com 300ml de capacidade, para nunca te deixar na mão, possui uma pegada emborrachada para não escorregar enquanto você vive suas aventuras! Feita em aço inoxidável, deixa sua bebida sempre na temperatura certa! Não importa se você é um super-herói ou não, essa caneca vai te ajudar a salvar o mundo! Especificações: Altura: 9cm| Largura: 7,5cm| Comprimento: 7,5cm | Peso: 0,300gr| Capacidade: 300ml| Material: Aço Inoxidável Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de aço.', 84.9, 84.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-820mf-mnegvtl633sz7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F22992246009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
