INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12646340374', 'Ração Úmida Sachê Friskies Gatos Filhotes Carne Ao Molho 85g', '- Indicado para gatos filhotes; - Mix de sabores e texturas deliciosamente surpreendentes; - Pedaços macios e suculentos; - +25%* de proteína; - Alimento 100% completo e balanceado; - Sem adição de conservantes artificiais; FRISKIES Filhotes Carne ao molho é um alimento úmido completo e balanceado destinado a filhotes de gatos de 1 a 12 meses e a fêmeas gestantes ou lactantes. Pele e pelos saudáveis graças aos níveis adequados de zinco e ácidos graxos essenciais. Visão clara e saudável devido à adição de vitamina A e taurina. Formulado com vitaminas e minerais que auxiliam nas defesas naturais. Músculos fortes e saudáveis devido à presença de fontes de proteínas de alta qualidade. Composição carne bovina, fígado suíno, fígado de frango, carne mecanicamente separada de frango, glúten de trigo, proteína concentrada de soja, amido de milho, dextrose, fosfato bicálcico, carbonato de cálcio, cloreto de sódio (sal comum), cloreto de potássio, água, taurina, glicina, vitaminas (A, D3, E, K3, B12, mononitrato de tiamina, suplemento de riboflavina, cloridrato de piridoxina, niacina, biotina, ácido fólico, pantotenato de cálcio, cloreto de colina), minerais (sulfato de zinco, proteinato de zinco, sulfato ferroso, sulfato de cobre, proteinato de cobre, sulfato de manganês, proteinato de manganês, iodato de cálcio, selenito de sódio), corantes (óxido de ferro vermelho e caramelo). Eventuais Substitutivos: miúdos de suínos e carcaça de frango.', 5.91, 3.92, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfl3u4zaonpc4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F12646340374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
