INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093056065', 'Sapatênis Pegada Masculino Microfibra Atanado 170422', 'Explore o conforto supremo com o sapatênis Pegada da linha Element! Fabricado com a inovadora microfibra PGD Fibertech, esse material tecnológico excepcional oferece alta flexibilidade, leveza e resistência. Reconhecida por sua durabilidade, a microfibra é uma escolha ideal para calçados de segurança. A transpirabilidade é uma marca registrada desse material, essencial para eliminar o suor dos pés. O forro em tecido espumado proporciona conforto e auxilia na absorção de suor, mantendo os pés secos e arejados. A palmilha macia oferece um toque adicional de conforto, enquanto o solado leve e flexível completa o pacote. E não podemos esquecer do sistema "Calce Fácil", com elásticos laterais que proporcionam praticidade ao calçar. Este modelo é perfeito para quem busca estilo sem abrir mão do conforto. Não espere mais! Adquira o seu sapatênis Pegada agora e experimente o equilíbrio perfeito entre estilo e conforto!', 269.89, 199.88, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zu6-mmj2e6tlacqr7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22093056065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
