INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42960153380', 'Frigideira Turim em Alumínio Antiaderente Chumbo 22cm / 1L (20260/622) - Tramontina', 'A Frigideira Turim em Alumínio Antiaderente Chumbo 22cm / 1L (20260/622) - Tramontina, é produzida em alumínio e com espessura de 1,2 milímetros, proporciona o cozimento rápido e uniforme dos alimentos. Ela possui revestimento interno e externo em antiaderente Starflon Max que evita que os alimentos grudem em sua superfície, a torna fácil de limpar e não prejudicial a saúde. Além de todas, essas características, para garantir maior segurança, o cabo em baquelite é um material antitérmico que não aquece. Ela pode ir à máquina de lavar louças e é uma frigideira indispensável para quem deseja praticidade em todos os itens da sua casa! Descrição do Produto: • Corpo de alumínio com espessura de 1,2 mm que proporciona cozimento rápido e uniforme. • Revestimento interno e externo de antiaderente Starflon Max que não gruda, é fácil de limpar, mais durável e não é prejudicial à saúde, pois é livre de PFOA. • Cabo de baquelite antitérmico que oferece segurança durante o manuseio. • Pode ir à máquina de lavar louças facilitando seu dia a dia. • Pode ser utilizada nos fogões: gás, elétrico e vitrocerâmico - resistência elétrica. Referência: 20260/622. Cód. de Fábrica: 20260/622. Marca: Tramontina.', 44.3, 44.3, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-mckz5p5kbtmf69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F42960153380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
