INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697491248', 'Shampoo Fortificante Sem Sal Hair Sun Protect Jacques Janine 200ml', 'Shampoo Hair Sun Protect fortifica e evita o envelhecimento dos cabelos. Além disso, forma uma camada protetora nos cabelos contra os danos externos, como sol, cloro, poluição e sal. Modo de Uso Aplique no cabelo molhado e massageie suavemente o couro cabeludo com a ponto dos dedos até obter espuma. Enxágue. Repita se necessário. Composição ÁGUA, LAURILETERSULFATO DE SÓDIO, COCAMIDA, COCAMIDOPROPIL BETAÍNA, OCTINOXATO, FRAGR NCIA, FENOXIETANOL, DIESTEARATO DE ETILENOGLICOL, LAURIL SULFATO DE AMÔNIO, CLORETO DE GUAR HIDROXIPROPILTRIMÔNIO, MONOESTEARATO DE ETILENOGLICOL, EDETATO DISSÓDICO, DIESTEARATO DE PEG-150, ETILHEXILGLICERINA, ÁCIDO CÍTRICO, POLIQUATÉRNIO-67, POLIQUATÉRNIO-7, POLIQUATÉRNIO-10, EXTRATO DA SECREÇÃO DO SACO DE PÉROLAS, EXTRATO DE CAVIAR, ÓLEO DE COCO, DIMETILIDANTOÍNA, LIMONENO, BRONOPOL, METHYLCHLOROISOTHIAZOLINONE AND METHYLISOTHIAZOLINONE /METILCLOROISOTIAZOLINONA E METILISOTIAZOLINONA.', 67.9, 39.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-lygir0huwzyf7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23697491248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
