INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254635706', 'Plastificadora A3 500W 220V Preta Para Documentos Fotos e Certificados', 'Plastificadora A3 500w 220v Documentos Escritório Preta Importway A solução ideal para proteger e conservar documentos, fotos, certificados e materiais escolares ou corporativos. Indicada para uso em escritórios, escolas e residências, proporciona acabamento uniforme, garantindo maior durabilidade contra umidade, sujeira e desgaste do tempo. Especificações: • Marca: Importway • Modelo: IWE013 • Potência: 500W • Voltagem (IWE013): 220-240V/60Hz Corrente: 2.1A • Tempo máximo de plastificação: 1 minuto • Largura máxima de laminação: 330 mm • Espessura máxima de laminação: 0,6mm • Velocidade máxima de laminação: 350mm/min • Botão frio e quente • Rolos: 2 unidades Conteúdo Embalagem: - 01 Plastificadora A3 500w 220v Documentos Escritório Preta Importway "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 443.08, 389.9, NULL, 'Stationery > School & Office Equipment > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260k-mkb7zggakphefe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242218284%2F58254635706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
