INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494687881', 'Tênis de Led Infantil Perolado Concha Strass Pampili', 'Cheio de estilo, este tênis infantil é o queridinho das meninas que amam brilhar! O cabedal com recortes de efeito holográfico suave reflete tons delicados e as luzes de LED brancas no cabedal deixam o visual ainda mais divertido.O solado caixa traz um toque contemporâneo e versátil, ideal para acompanhar as meninas em todas as ocasiões. Com fecho de contato e elástico, o calce é prático, proporcionando autonomia para as pequenas. O forro com espuma macia mantém os pés confortáveis e secos, enquanto a palmilha anatômica oferece amortecimento e bem-estar. O solado com identificação em braile auxilia na diferenciação dos pés para meninas cegas ou com baixa visão promovendo a inclusão. Aposte! Combine com vestidinhos leves e mochilas coloridas, ou com shorts e blusas estilosas, criando looks cheios de charme e personalidade!', 269.9, 188.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8224w-mhca934y0v7s00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F22494687881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
