INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997094358', 'Livro A queda da casa de Usher', 'Roderick e sua irmã gêmea, Madeline, são os únicos herdeiros da tradicional e misteriosa família Usher. Ao chegar na casa, o narrador se surpreende com o ambiente assustador onde seu amigo vive. A famosa Casa de Usher parece estar envolvida por uma atmosfera opressiva, que causa calafrios em seu visitante._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2023_x000D_ Autor: Edgar Allan Poe_x000D_ Ilustrador: Cesar Munoz Moreno_x000D_ Idioma: Português_x000D_ Páginas: 64_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.50_x000D_ ISBN: 9786550971038_x000D_ Coleção: Clássicos da literatura mundial_x000D_ Linha Editorial: Principis - Clássicos da literatura_x000D_ Faixa Etária: + 16 anos_x000D_ Assuntos (tags): Terror, Mistério, Medo, Ficção, Góticos, Sensações, Ansiedade, Estados Unidos, Horror, Sobrenatural, Doença_x000D_ BISAC: Ficção / Gótica_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 24.9, 24.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rbky-lnj4857r5xvs02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22997094358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
