INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8570275344', 'Livro - Viagem ao centro da Terra - Principis', 'O professor Lidenbrock consegue decifrar um enigma do pergaminho de um cientista do século XII e se junta ao seu sobrinho, o jovem Áxel, para checar a possibilidade de chegar ao centro da Terra seguindo o relato decifrado. Editora: Principis Edição: 1, 2019 Autor: Júlio Verne Idioma: Português Páginas: 304 Dimensões: L 16.00 x A 23.00 x E 1.80 ISBN: 9788594318152', 29.9, 29.9, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/22da1368ad56a01702b480741eb5ff9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8570275344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
