INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399571417', 'Eleição | C. H. Spurgeon', 'Eleição | C. H. Spurgeon Neste sermão, C. H. Spurgeon, conhecido como o "Príncipe dos Pregadores", declara com convicção: "Não estou pregando aqui nenhuma novidade, nenhuma doutrina nova." Ele celebra e proclama com fervor as antigas verdades do Evangelho, aquelas que foram anunciadas por Cristo e pelos grandes líderes da igreja ao longo da história. Através da doutrina da eleição, Spurgeon remonta ao passado, evocando a presença espiritual dos pais da igreja, dos mártires e dos reformadores, que se levantaram para defender a mesma fé que ele prega. Para Spurgeon, essas doutrinas centrais são o alicerce de sua própria fé e uma herança espiritual que une os cristãos de todas as gerações, reconhecendo que essa é a verdadeira religião da igreja de Deus. Altura: 16 cm Largura: 12 cm Profundidade: 0,5 cm Páginas: 64', 21.18, 21.18, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rene-m2wpmdybuy2kdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18399571417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
