INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497415318', 'Meia Galochita Menina Meia Colorida Para Galocha Infantil Feminina', 'Encante sua pequena com o conforto e aconchego da nossa Meia para Galocha Infantil Feminina. Criada especialmente para acompanhar aventuras em dias chuvosos, esta meia é um complemento essencial para os pés das pequenas. Feita com uma mistura suave de algodão e elastano, esta meia proporciona um ajuste confortável e flexível, garantindo liberdade de movimento enquanto mantém os pezinhos secos e protegidos dentro da galocha. Seu design encantador apresenta cores vibrantes, desde estampas listradas coloridas até corações coloridos, tornando cada passo uma experiência divertida e estilosa! Composição: 70% Algodão 28% Poliamida 02% Elastano Tabela de Medidas: Tamanho P – Veste 22 ao 25 Tamanho M – Veste 26 ao 29 Tamanho G – Veste 30 ao 33', 49.9, 21.95, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Socks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lt3q39cxmudr91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F22497415318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
