INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20635127424', 'Kit Desinfetante Pinho Sol Original 500ml com 5 unidades', 'Kit Desinfetante Pinho Sol Original 500ml com 5 unidades Elimina 99,9% das bactérias, germes e fungos Pinho Sol Original é um desinfetante que limpa e elimina 99,9% das bactérias/ germes e fungos*. Além disso, possui um delicioso perfume de Pinho, deixando a sua casa sempre limpa protegida e com um agradável perfume que dura por muito mais tempo. Use em todos os cômodos da casa e em diversas superfícies como: vaso sanitário, ralo, pia, tanque, azulejos e pisos. Quer saber como usar? É fácil: – Para desinfecção, utilize o produto puro e deixe-o agir em contato com a área por 30 segundos. – Para limpeza geral de superfície, dilua 2 colheres de copa (30ml) por litro de água. Seguindo essa instrução, o produto rende até 16 litros. – Para lavar roupa utilize um copo americano (200ml) de Pinho Sol com sabão ou detergente em um tanque ou máquina de lavar cheios de água. Para manchas, basta umedecer a parte suja com Pinho Sol e colocar a peça na máquina de lavar ou tanque. 1.75 L – Rende até 87 litros 1L – Rende até 50 litros. 500ml – Rende até 25 litros. Disponível nos tamanhos: 1.75L, 1L e 500ml', 61.59, 61.59, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/aaabd7b0f2fe028fc925236946dba172', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F20635127424', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
