INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197634775', 'Jogo de Taças de Cristal Transparente Fio de Ouro Imperial 330mL 2 peças - Lyor', 'Conjunto de Taças de Cristal 330ml 2 peças Imperial Transparente Fio de Ouro- Lyor O conjunto de taças Imperial possui design moderno e sofisticado, com desenhos em relevo no cristal que se assemelham as decorações da realeza, para você servir deliciosas bebidas com requinte e bom gosto. O kit de taças Imperial da Lyor 2 peças é produzido em cristal espesso de ótima qualidade e resistência, que garante uma ótima durabilidade ao jogo e ajuda a manter a temperatura de sua bebida. As taças são produzidas na cor transparente com a borda dourada e possuem 330ml de capacidade, são ideais para água, suco e refrigerante durante um jantar. As taças podem ser utilizadas na decoração de sua mesa posta, cristaleira, ou somente para dar um toque especial em sua cozinha ou sala de jantar. Composição e Dimensões: 2 taças de 330mL - 16,5cm (A) x Ø 8,5cm Características: Marca: Lyor Referência: 5740 Modelo: Imperial Material: Cristal Cor: Transparente com Borda Dourada Imagens ilustrativas.', 61.9, 46.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7rccs-lslmgrsp0x6f05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F504745949%2F20197634775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
