INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262261916', 'Par De Amortecedor Mola A Gás Capô Tampa Dianteira Duster 2021 2022 2023 Até 2027', 'Par de Amortecedores do Capô Renault Duster (2021 a 2027) – Todas as Versões e Modelos Mais praticidade, conforto e segurança para o seu SUV! Se os amortecedores do capô da sua Renault Duster perderam a pressão e o capô já não permanece aberto sozinho, este par é a substituição ideal para restaurar a funcionalidade e a segurança original do veículo. Produzido com componentes de primeira linha, oferece excelente pressurização, encaixe perfeito e alta durabilidade, superando as opções de baixa qualidade disponíveis no mercado. Evite acidentes durante inspeções e manutenções, garantindo mais conforto e praticidade no dia a dia. Garanta já o seu kit com excelente custo-benefício! ESPECIFICAÇÕES TÉCNICAS -- Conteúdo: 2 amortecedores (1 par) -- Aplicação: Capô dianteiro -- Comprimento aberto: 589 mm (58,9 cm) – centro a centro -- Comprimento fechado: 344 mm (34,4 cm) – centro a centro -- Sistema de fixação: encaixe por trava (padrão original) -- Cor: preto fosco automotivo -- Produto novo, resistente e de excelente acabamento -- Instalação simples e rápida -- Garantia de fábrica: 3 meses -- Envio imediato com nota fiscal INFORMAÇÕES IMPORTANTES -- As molas a gás novas possuem alta pressão e somente reduzirão seu comprimento após a instalação correta no veículo. Não tente comprimi-las manualmente ou fora do veículo. -- Recomenda-se a substituição do par completo para garantir a sustentação correta do capô, evitando desgaste prematuro das peças e garantindo o funcionamento adequado do sistema. COMPATIBILIDADE Renault Duster 2021 a 2027 – Todas as versões e modelos Versões compatíveis: -- Life -- Zen -- Intense -- Iconic -- Intense Plus -- Iconic Plus Motores compatíveis: -- 1.3 TCe Turbo -- 1.6 16V SCe Carroceria compatível: -- SUV 5 portas Transmissões compatíveis: -- Manual -- X-Tronic Aplicação: -- Compatível com todas as versões da Renault Duster fabricadas entre 2021 e 2027, incluindo modelos Life, Zen, Intense, Iconic, Intense Plus e Iconic Plus equipados com motores 1.3 TCe Turbo e 1.6 16V SCe, nas versões manuais e X-Tronic.', 78.99, 51.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820lr-mq54iyg6ll368c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F687222661%2F58262261916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392597448', 'Prato Sobremesa Lanche Flat Chuvisco 20cm 6 Unidades Oxford Jogo De Pratos', 'SOBRE O PRODUTO A linha Flat chega para complementar as cerâmicas da Oxford agregando versatilidade e beleza ao servir. Os pratos Flat oferecem uma área maior de uso tornando-se uma opção adequada para empratamentos criativos, além de proporcionarem mais conforto na hora de usar. Com formas retas e funcionais, as peças da linha são fáceis de armazenar até mesmo em armários mais compactos. Com inspiração na natureza, a decoração Chuvisco possui acabamento brilhante com base off white e pequenos detalhes em preto, que imitam gotas de chuva. Conjunto é composto por 6 pratos sobremesa. CONTEÚDO DA EMBALAGEM 6 Pratos Sobremesa Flat 20cm ESPECIFICAÇÕES Uso: Resistente a micro-ondas, Resistente a lava-louças Decoração: Flat Chuvisco Formato: Redondo Material: Cerâmica Cor: Branco, Preto Garantia: 90 dias (Defeitos de fabricação)', 199.99, 199.99, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnhmdiihemz05b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455103761%2F22392597448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
