INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13938780536', 'Broca de wídea para concreto 8 x 160 mm - SDS PLUS - Stamaco', 'Produto: Broca de wídea para concreto 8 x 160 mm - SDS PLUS Marca: Stamaco Descrição: A Broca de Wídea para Concreto 8 x 160 mm - SDS PLUS da Stamaco é desenhada para operar com marteletes que possuem encaixe SDS-Plus, esta ferramenta é a escolha ideal para usuários que buscam alto desempenho em perfurações em concreto, alvenaria e pedras. Características: • Precisão Incrível: Realiza perfurações rápidas e precisas, garantindo resultados excepcionais até mesmo nos materiais mais duros. • Alta Eficiência: Supera brocas convencionais em desempenho, permitindo uma operação mais ágil e menos trabalhosa. • Versatilidade Ampliada: Ideal para uma diversidade de aplicações na construção civil, mostrando-se útil em várias etapas do projeto. • Durabilidade Excepcional: Fabricada com aço de alta qualidade e ponta de vídea, resiste ao desgaste e estende a vida útil do produto. Projetada especificamente para o encaixe SDS-Plus, a Broca da Stamaco é uma ferramenta indispensável para a realização de trabalhos em construção civil, proporcionando uma experiência de uso segura e eficiente. Seja perfurando concreto, alvenaria, pedras, tijolos ou blocos, você pode confiar na Broca de Wídea da Stamaco para acabamentos perfeitos e uma execução sem igual. Especificações: Tamanho: 8 mm Material: Corpo em aço de alta qualidade com ponta de vídea" Encaixe: SDS-Plus. Peso: 0.06 Kg', 26.32, 26.32, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259o-mr0urkk30f7m43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F13938780536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
