INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254572860', 'Coenzima Q10 100mg Yoha 30 Cápsulas Ubiquinona Antioxidante Suporte Nutricional Diário Camila Loures', 'Coenzima Q10 100mg Yoha 30 Cápsulas Ubiquinona Antioxidante Suporte Nutricional A Coenzima Q10 Yoha 100mg foi desenvolvida para quem busca incluir na rotina um suplemento com composição prática e alta concentração de ubiquinona. Com 100mg por cápsula, sua fórmula auxilia no suporte nutricional diário e contribui para uma rotina equilibrada e funcional. A CoQ10 é reconhecida por sua atuação antioxidante, sendo uma excelente aliada para quem valoriza bem-estar, cuidado contínuo e qualidade de vida. Sua apresentação em cápsulas facilita o consumo no dia a dia, trazendo praticidade para a rotina. Destaques do produto 100mg de Coenzima Q10 por cápsula 30 cápsulas Ubiquinon Fórmula prática para o dia a dia Auxilia no suporte antioxidante Não contém glúten Sem adição de açúcares Composição Coenzima Q10, celulose microcristalina, estearato de magnésio e dióxido de silício. Componentes da cápsula: gelatina, glicerol, água destilada e corantes. ALÉRGICOS: Pode conter traços de leite e soja. NÃO CONTÉM GLÚTEN. Informação Nutricional Porção: 0,4g (1 cápsula) Coenzima Q10: 100mg Conteúdo da embalagem 1 Coenzima Q10 Yoha 100mg Frasco com 30 cápsulas', 89.9, 41.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-820lt-mo7855idnitc3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648042360%2F58254572860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
