INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197762311', 'Óleo Motul 7100 10w40 Para Motor 4 Tempos 100% Sintético 1 Litro', 'Óleo Motul 7100 10W40 100% Sintético 4 Tempos 1 Litro Especificações Técnicas: - Aplicação: Lubrificantes para motor - Tipo de motor: 4 Tempos - Qualidade: 100% Sintético - Viscosidade: 10W40 - Padrão API: API SP - Padrão JASO: JASO MA2 M033MOT125 - Origem: Itália - Número de Registro ANP: 22.249 Lubrificante 100% sintético para maior resistência da película de óleo em altas temperaturas e rotação elevada. Tecnologia Ester de baixo coeficiente de tração para minimizar as perdas por atrito dentro do motor e melhorar o desempenho. Sinergia do Ester com aditivos antidesgaste e resistência melhorada à degradação da viscosidade para melhor proteção e durabilidade das engrenagens. Homologação JASO MA2 oferece os níveis de atrito mais eficazes para garantir o acoplamento da embreagem durante 3 momentos chave na condução: partida, aceleração e velocidade constante.', 189.9, 170.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2eqalst98i47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F21197762311', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191993589', 'Filtro de Óleo Hornet 600 / Cb 500 / Ninja 300 / Versys 300 / Mt 03 Mt 07 Mt 09 / Xj6 Tecfil', 'A principal função do filtro de óleo, é impedir a passagem de partículas indesejáveis (proveniente da fricção das peças) para dentro do motor evitando assim desgastes excessivos dos componentes internos durante seu funcionamento. Principais Aplicações: CB 500, NC 700X, NC 750X, MT 03 , MT 07, MT 09, XJ6, NINJA 300, Z 300, VULCAN 650, VERSYS 300, VERSYS 650 Especificações Técnicas: - Fabricado em Metal e Borracha Resistente - Possui Válvula Anti-Dreno, Desvio e Alívio PSI - Para Uso de Óleo Mineral, Sintético e Semi-sintético - Projetado Para Suportar Pressões Internas Elevadas - Garante Melhor Circulação do Óleo e Proteção ao Motor - Maior Resistência a Pedras e Detritos que Podem Atingir a Moto - Borracha de Vedação Pré-Lubrificada - Substitui o Filtro de Óleo Original - Fácil Instalação Vantagens do Filtro: - Protege o motor; - Prolonga sua vida útil; - Proporciona segurança; - Permite uma lubrificação mais eficaz; - Proporciona melhor rendimento do motor e precisão de funcionamento; - Contribui na economia de combustível; - Contribui para a redução de emissão de poluentes na atmosfera Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 39.9, 31.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7qveb-ljfw8q1xp9vt35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F23191993589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
