INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19272095100', 'Filtro de Ar Biz 110i / Biz 125 Vedamotors', 'Filtro de Ar Vedamotors Os filtros de ar Vedamotors são projetados com todas as características necessárias para o excelente funcionamento do motor, filtrando quaisquer impurezas e deixando livre apenas a passagem de ar necessária para a melhor potência do motor com maior durabilidade. O papel utilizado nos filtros são mais densos, proporcionando maior grau de filtragem. Os filtros de ar da linha off-road da marca Athena, esses são fabricados com camadas de poliuretano de células abertas. Compatível com: HONDA BIZ 110 I 2016 em diante BIZ 125 ES 2011 em diante BIZ 125 EX 2011 em diante BIZ 125 KS 2011 em diante Código Original: 17220-KSS-J30 Vantagens: - Motor limpo (Livre de impurezas que possam comprometer o seu funcionamento de forma prematura) - Economia de combustível. O Filtro de ar Vedamotors é projetado com todas as características necessárias para o excelente funcionamento do motor, barrando quaisquer impureza e deixando livre apenas a passagem de ar necessária para a melhor potência do motor com maior durabilidade. Especificações Técnicas: - Qualidade em elementos filtrantes, desenvolvido para motores de alto desempenho; - Proporciona Melhor Queima de Combustível e Ajuda a Diminuir a Emissão de Gases Poluentes - Oferece Menor Desgaste dos Componentes Internos do Motor - Filtro Seco - Rígido - Maior Durabilidade e Qualidade de Filtração - Filtro de alto padrão desenvolvido com elementos filtrantes que equivalem as características técnicas exigidas pelos fabricantes de motocicletas - Fluxo de ar: Compatível com a especificação do fabricante - Não Lavável Importante: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 59.9, 47.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me8nw1xwyoe90c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F19272095100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6386345710', 'Kit Borrachas De Vedação Ford Ka 2 Portas 1997 1998 1999 2000', 'Temos o prazer de trazer mais um produto de excelente qualidade, sucesso de vendas com preço justo! Kit Borrachas De Vedação de 2 Portas Essa é a borracha que faz o contorno da porta, vai fixada na carroceria, evitando que entre água, poeira para dentro do veiculo, diminuindo até barulhos internos e amortecendo o fechamento da porta. Essas borrachas protetoras são conhecidas como guarnição. Compatível com Ford Ka 2 Portas - .1997 1998 1999 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 Borrachas na cor Preta. Acabamento com aba. Fixado por encaixe. Produto de excelente qualidade 100% garantido. Para outros carros e modelos, entre em contato conosco. Garantia de 3 meses', 158.9, 158.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/8d4d17dd6adfc8b091755c75693314bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F6386345710', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
