INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197425364', 'Toalhinha Infantil Johnson''s Baby Recém Nascido Hipoalergênica C/48Un', 'As Toalhas Umedecidas Johnsons''s Baby Recém Nascido, da Johnson & Johnson foram desenvolvidas para cuidar de maneira especial limpando todas as sujeirinhas de forma suave e eficiente. São produzidas com fibras mais macias e espessas, fazendo com que sejam suaves ao toque na pele delicada do bebê, mais absorventes e super-resistentes. Desenvolvidas com a fórmula Chega de Lágrimas, podem ser utilizadas em todo o corpinho do bebê, inclusive ao redor dos olhos. Seu bebê seguro desde o primeiro dia de vida! Modo de Uso: Retire a toalhinha puxando pelo centro. Após o uso feche a embalagem. Manter sempre a etiqueta autoadesiva ou o pote fechado entre um uso e outro para manter a umidade do produto. Após o uso descartar a toalhinha no lixo.', 27.99, 27.99, NULL, 'Mom & Baby > Bath & Body Care > Wipes', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-lmj2qxsurl96bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18197425364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597205293', 'Alarme Automotivo Fks Fke515 Ford Ka 2015 Em Diante', 'Alarme FKS FKE515 com Chaveador Eletrônico Original: Proteção e Conveniência para o Seu Veículo! Descrição do Produto: Apresentamos o Alarme FKS FKE515, um sistema de segurança automotiva de alto desempenho, projetado para proporcionar a máxima proteção ao seu veículo. Com o Chaveador Eletrônico Original, você tem a garantia de qualidade e eficiência que só a FKS oferece. Principais Características: • Chaveador Eletrônico Original: Conte com a tecnologia exclusiva da FKS, que assegura o melhor desempenho e confiabilidade para a proteção do seu automóvel. • Disparo Imediato: Em caso de tentativa de furto, o alarme dispara imediatamente, impedindo qualquer ação indesejada e garantindo a segurança do seu veículo. • Compatibilidade Universal: O Alarme FKS FKE515 é compatível com o ford Ka 2015 em diante • Travamento Automático de Portas: Ao ligar a ignição, as portas travam automaticamente, proporcionando segurança instantânea durante a condução. • Bloqueio do Motor Integrado: Aumente a proteção do seu veículo com o bloqueio do motor, impedindo que intrusos o levem mesmo em caso de violação do alarme. • Facilidade de Controle: O controle remoto possui botões intuitivos que permitem acionar e desativar o alarme com facilidade. • Funções Programáveis: Personalize o alarme de acordo com suas preferências, ajustando o tempo de travamento, o tom da sirene e outras configurações. Recursos Extras: Conte com funções pânico, localizador e check control para uma experiência completa de segurança e controle do seu veículo.', 194.25, 174.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/br-11134201-820ma-mqxb4fowyivbe3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F18597205293', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
