INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54959126856', 'Lovito Shorts Feminino Plus Size com Botões STB13BR308', '✅DESTAQUES -❤️Confortável -❤️Elegante ✅DESCRIÇÕES Estampa: Não Coleção: Ano Todo Tamanho Plus: Sim Composição: 92% Poliéster 8% Elastano Tipo de Modelagem: Plus Size Transparência: Não Elasticidade: Não Região de Origem: Brasil ✅REFERÊNCIA DE MODELAGEM A modelo está vestindo: 1XL ✅O PACOTE INCLUI 1 Shorts ✅INTRODUÇÃO À LOVITO A Lovito é uma marca emergente que acredita no poder feminino, comprometida em oferecer opções de roupas elegantes e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, entre em contato conosco e responderemos o mais rápido possível.😊', 76.9, 56.9, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/br-11134207-820m8-mofjdjcwvz7pf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F54959126856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12772316781', 'Par Aro Adaptador Alto Falante Citroen C3 Traseiro - 696', 'Aro Adaptador para alto falantes 5 Polegadas - traseiro Citroen C3 Descrição do Produto - Produzido em plástico de alta resistência - Para linha Citroen C3 - Para alto falantes de 5 polegadas - Evita fazer novos furos - Utiliza a furação original - Cor preto - Ótima Qualidade Itens Inclusos 02 unidades - Aro Adaptador p/ Falantes traseiro - Produto Novo - Produto de Ótima Qualidade - Com Material de Alta Resistência Envio imediato !!! Postamos seu pedido em 24 horas !!! Sua encomenda segue com seguro e rastreamento O melhor custo-benefício IMPORTANTE !!! -Verifique a compatibilidade do produto com seus equipamentos para que não haja problemas na hora do uso! -Antes da instalação deve ser feito o teste em bancada para que não ocorra a perda da garantia. -A instalação deve ser feita por um profissional capacitado, não nos responsabilizamos por uso indevido ou instalação incorreta. Política de garantia, troca e devolução. A DEVOLUÇÃO POR INSTALAÇÃO OU OUTROS MOTIVOS Poderá ser feita em até 7 dias corridos após o recebimento do produto, desde que com a embalagem original, junto com todos os acessórios que o acompanham, manual e embalagem deverão estar preservados, sem fitas coladas, etiquetas ou algo que a descaracterize. O Produto não poderá haver sido instalado, e sim somente testado em bancada, esse é um procedimento comum feito por instaladores profissional antes de fixar o produto no veículo, e obrigatoriamente todos os produtos que exigem instalação devem ser instalados por profissional devidamente habilitado. A DEVOLUÇÃO/TROCA POR DEFEITO DE FABRICAÇÃO Produtos com defeito somente serão trocados se cumpridas as mesmas condições de devolução, de não instalação, dentro dos 7 dias corridos após o recebimento, sem marcas de uso, do contrário serão enviados à assistência técnica do fabricante para conserto e devolução dentro dos prazos que rege a lei do consumidor vigente (CDC). A GARANTIA DO FABRICANTE Alguns fabricantes dispõe de garantia direta ao consumidor, e nesse caso a troca por defeito, ou a garantia de assistência técnica só poderá ser feita diretamente nos postos autorizado, não sendo feita através do revendedor. Mesmo estando dentro do prazo de 7 dias corridos do recebimento, produtos como DRIVERS E SUPER TWEETERS, possuem garantia somente para defeitos de fabricação, não são cobertos queima ou avaria de reparo, seja ele de qualquer natureza que não a de fabricação. Não serão aceitos devoluções de produtos avariados, queimados, riscados, amassados, por instalação, manuseio, uso ou transporte incorretos, fora da embalagem original ou com a mesma danificada.', 40.88, 39.86, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/d1a6e6756dbfcb51ce8e71ad82891fa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278273583%2F12772316781', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
