INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599230056', 'Kit com 3 Encordoamentos Elixir 011 Custom Light Phospor Bronze para Violão Aço', 'Kit com 3 Encordoamentos Elixir 011 Custom Light Phospor Bronze para Violão Aço Revestimento Nanoweb permite que as cordas da guitarra tenham a sensação, o tom brilhante de cordas tradicionais. Elixires são a primeira grande inovação em cordas em mais de quarenta anos, e eles entregam o que prometem: grande Tom e longa vida, não importa o que você colocá-los em ou quantas vezes você irá tocar. As cordas Elixir de aço são cobertas com uma camada de polímero ultra-fino, da era espacial que tem contato com a corda apenas no topo dos enrolamentos. Isso deixa o todo-importante enrolamento-de-enrolamento-de-núcleo livre dos inimigos do tom! Além de um revestimento ultra-fino resistente, Nanowebs têm agora uma revolucionária película anti-ferrugem nas cordas para prolongar a sua vida também.', 496.99, 496.99, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rce2-lte1kvlfa3af86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F19599230056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
