INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57156283004', 'Bálsamo De Limpeza Apertador De Poros REJURAN , 50mL', 'Descrição do produto 💜 Um bálsamo de limpeza de poros apertado infundido com o PDRN de assinatura da REJURAN para derreter A maquiagem e as impurezas ao reabastecer A umidade. 💜 O sebo suave dissolve a maquiagem pesada, protetor solar e excesso sem retirar a pele 💜 O bálsamo para óleo sedoso ao entrar em contato com a pele para uma limpeza suave, mas poderosa. 💜 A pele fica limpa, hidratada e refinada após o enxágue. Características e benefícios das chaves ✨ Cuidados com o aperto dos poros dos poros Ajuda a melhorar a aparência dos poros dilatados para uma tez mais suave. ✨ Reabastecimento da umidade da umidade da umidade Evita o aperto após a limpeza e mantém o equilíbrio de hidratação da pele. ✨ Fórmula de aumento de pele para a pele Alimentado pela tecnologia DOT C-PDRN avançada da REJURAN para suporte intensivo à pele. ✨ Efeito de cuidados triplos ✔ Alta pureza ✔ Alta concentração ✔ Alta estabilidade de alta estabilidade Melhoria da condição da pele (resultados clínicos de teste) 📉 PretoCabeças de cabeças: -47,75% 📉 Rugosidade da pele: -10,99% 📈 Umidade da pele da pele: +141,22% Com base em resultados de teste clínicos. Os resultados individuais podem variar. Livre de grátis de 🚫 Parabeno 🚫 Corantes Artificiais 🚫 Fragrância Artificial Textura de textura Bálsamo macio semelhante ao sherbet que derrete instantaneamente em óleo e emulsiona facilmente com água para enxaguar limpo sem resíduos. Como usar 1. Colher de Scoop de uma quantidade adequada nas mãos secas. 2. Massageie suavemente no rosto seco para dissolver maquiagem e impurezas. 3. Adicione uma pequena quantidade de água para emulsionar. 4. Enxágue bem com água morna.', 124.34, 124.34, NULL, 'Beauty > Makeup > Makeup Removers', 'https://cf.shopee.com.br/file/sg-11134207-8260j-mkw8yjhwy4n684', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F57156283004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
