INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18758142090', 'Cesto Suspenso Para Prateleira M Verde Oliva Bel', 'Cesto Suspenso Para Prateleira Bel – Praticidade e Organização em Qualquer Espaço O Cesto Suspenso Para Prateleira Bel é a solução perfeita para otimizar o espaço em armários e closets, criando um segundo nível nas prateleiras e aproveitando ao máximo o espaço superior. Versátil e funcional, ele permite organizar diversos itens com praticidade, sem a necessidade de fixação nos móveis, tornando sua instalação rápida e simples. Ideal para quem busca ganhar mais espaço em casa e otimizar a rotina, o cesto é removível, durável e seguro. Sua aplicação vai além de armários, podendo ser utilizado em diferentes ambientes para armazenar diversos tipos de produtos. Produzido em aço carbono com pintura eletrostática a pó (epóxi), o Cesto Suspenso Para Prateleira Bel oferece alta resistência e qualidade, garantindo maior durabilidade e um design moderno para o seu lar. . Fácil encaixe em prateleiras de 1,5 cm a 2 cm de espessura. . Suporta até 5 kg distribuídos de forma uniforme. . Não necessita de ferramentas para montagem, facilitando sua instalação. . Suas medidas são : comprimento 37 cm, largura 24 cm, altura 14,5 cm.', 42.9, 32.9, NULL, 'Home & Living > Home Organizers > Others', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mfsgf9nzme4s81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F18758142090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
