INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799263858', 'Alto Falante Subwoofer Jbl 18" 1200w Rms 18SW5P 8 Ohms Profissional', 'DESCRIÇÃO: O novo Subwoofer 18" JBL Selenium 18SW5P - 1200 Watts RMS é um alto-falante chamado subão. Possui características de muito subgrave mas possui alto rendimento para fora, com capacidade de jogar o grave longe. Com sensibilidade de 96 dB e impedância de 8 Ohms, é perfeito tanto para som profissional quanto para som automotivo. Carcaça em alumínio e imã em ferrite de bário garantem alta qualidade ao falante. ESPECIFICAÇÕES TÉCNICAS: Subwoofer 18" JBL Selenium 18SW5P Potência: 1200 Watts RMS Impedância: 8 Ohms Diâmetro: 45,7 cm Sensibilidade: 96 dB Resposta de frequência: 37 ~ 2000 Hz Fs: 35 Hz Qms: 5,54 Qes: 0,40 Qts: 0,37 Vas: 253 l Referencia de eficiência: 2,64 % Xmax: 9,6 mm Caixa dutada: 200 litros', 1458.67, 1250.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-824j7-me06g3xrrpc783', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F20799263858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17927098390', 'Tablet Galinha Pintadinha Wi-Fi 32GB Tela 7 Android 11 Go Edition com Controle Parental Multilaser - NB373', 'Com o Tablet Galinha Pintadinha Multilaser a diversão nunca tem fim!<br /> Desenvolvido com o super processador Hardware Quad Core, você pode jogar, ver vídeos, navegar na internet e muito mais, ao mesmo tempo e sem travamentos ou lentidão, devido ao sistema operacional Android 11 (GO EDITION) que permite turbinar seu tablet com milhares de aplicativos no Google Play.<br /> Além disso, os pais podem ficar tranquilos já que o Tablet da Galinha Pintadinha possui um sistema de Controle Parental que permite à criança utilizar o tablet com muito mais segurança! <br /> Indicado para +3 anos. Vem com case emborrachado que permite ajuste de ângulo facilitando o uso do seu pequeno!<br /> Já vem com jogos e aplicativos pré-instalados para a garotada se divertir sem parar!!<br /> <br /> Imagens meramente ilustrativas.', 625.9, 625.9, NULL, 'Mobile & Gadgets > Tablets', 'https://cf.shopee.com.br/file/1b2edd874ae7a8a5de50e837b09466e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F17927098390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26944325645', 'Lavatório Champ Smart Preto 2040 Dompel Profissional Salão de Beleza e Barbearia', 'O Lavatório Champ Smart Dompel é ideal para salões de beleza e barbearias que buscam conforto, resistência e praticidade no atendimento. Possui estrutura modular inteligente, que facilita transporte, armazenamento e montagem, sendo perfeito também para vendas online. Fabricado em polipropileno de alta resistência com componentes em aço galvanizado, garante durabilidade e estabilidade no uso profissional. O estofado com espuma e revestimento sintético tipo courvin oferece maior conforto ao cliente e fácil limpeza. A cuba profunda proporciona melhor acomodação na lavagem dos cabelos, enquanto a prateleira central permite organizar shampoos, cremes e acessórios. ✔ Ideal para salão de beleza e barbearia ✔ Estrutura resistente e durável ✔ Cuba profunda para maior conforto ✔ Estofado confortável e fácil de higienizar ✔ Prateleira para organização de produtos ✔ Fácil transporte e montagem Características do Produto: Marca: Dompel Modelo: Champ Smart 2040-AP Cor: Preto Estrutura em polipropileno de alta resistência Componentes metálicos em aço galvanizado Estofado em espuma com revestimento sintético (courvin) Sistema reclinável 1 entrada de água Acompanha ducha, ralo e kit de fixação Não acompanha aquecedor de água Dimensões Aproximadas: Altura: 113 cm Largura: 59,5 cm Profundidade: 91 cm Peso: 12,8 kg Conteúdo da Embalagem: 1 Lavatório Champ Smart Preto 1 Registro (1 entrada de água) 1 Ducha 1 Ralo 1 Kit de fixação', 1247.87, 749.9, NULL, 'Beauty > Beauty Tools > Others', 'https://cf.shopee.com.br/file/br-11134207-820lm-mq6ic1fas5c1af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F26944325645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00