INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201955859', 'Kit 2 Capacetes De Moto Pro Tork Evolution G8 Evo Rosa Mais Variações', 'O Evolution G8 traz um novo design mais aerodinâmico, com aerofólio reforçado que garante mais estabilidade na pilotagem. Conta também com um sistema de ventilação mais prático para o dia a dia e um interior mais confortável. É a escolha ideal para quem busca segurança, conforto e estilo. Características: Modelo: Evolution G8 Evo Tamanhos: 56, 58, 60 e 62 Novas cores e grafismos modernos Forração confortável Sistema de ventilação prático Casco em ABS resistente Fecho micrométrico de engate rápido Viseira cristal de 2mm em policarbonato Certificado pelo INMETRO e DOT Marca: Pro Tork Dica de tamanho: Escolha um capacete bem justo, pois ele se ajusta com o uso. Ex: se você mede 56/57 cm, pode optar pelo 56. Limpeza: Remova o forro e lave com detergente neutro Pode usar máquina no modo delicado Secar à sombra Evite mergulhar o capacete na água Deixe sempre arejado Importante: Não use produtos em aerosol, pois podem danificar o capacete. Garantia: 90 dias', 652.42, 434.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-820m7-mnonre2fdla914', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F58201955859', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11771009474', 'Kit 8 Escova Dental Colgate Slim Soft Black', 'Kit 8 Escova Dental Colgate Slim Soft Black A Escova Dental Colgate Slim Soft Black foi desenvolvida com a tecnologia de ponta da Colgate. Por meio de cerdas macias infundidas em carvão com pontas ultrafinas, a escova promove uma limpeza profunda e delicada. * Kit Contém: 2 Ebalagens Escova Dental Colgate Slim Soft Black com 4 unidades cada * Compre Produtos Colgate.', 99.49, 99.49, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/50709a6852c3b7bec5e535daccc71037', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F11771009474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
