INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594617946', 'Kit Wella Professionals Fusion Shampoo e Condicionador 1L (2 produtos)', 'Kit Wella Professionals Fusion Salon Duo (2 Produtos) Kit em tamanho salão para cabelos danificados. Kit Wella Professionals Fusion Salon Duo ajuda a recuperar a fibra capilar dos danos e evita a quebra. Kit Wella Professionals Fusion Salon Duo faz uma limpeza delicada no cabelo, sem comprometer a saúde da fibra capilar, além de deixar os fios mais suaves e desembaraçados. Sua fragrância combina nove aromas que remetem à sofisticação, com seus toques de madeira florestal e notas de base quentes, como cedro e sândalo. Contém Wella Professionals Fusion - Shampoo 1000ml: limpa e auxilia na reparação dos danos. Wella Professionals Fusion - Condicionador 1000ml: impede a quebra dos fios causados por agressões mecânicas. Ação Fusion Silksteel: fusão de aminoácidos da seda e lipídios micronizados que penetram no interior do córtex para recuperar a condição ideal do fio e deixar o cabelo até 95% mais resistente. Tecnologia EDD: age na camada externa do fio para remover as impurezas com sua ação antioxidante. Como Usar Kit Wella Professionals Fusion Salon Duo (2 Produtos) Conselho de Aplicação Aplique o shampoo sobre a raiz do cabelo molhado e massageie até formar espuma. Puxe o produto para a extensão e pontas. Enxágue. Se necessário, repita o procedimento. Espalhe o condicionador sobre o comprimento e pontas do cabelo úmido. Deixe agir por 30 segundos e enxágue. Resultado Seu cabelo fica limpo, desembaraçado, mais resistente e com um perfume luxuoso.', 799.9, 550.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg6x83ays5c4f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23594617946', NULL, NULL, '2026-07-28T