INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46058915219', 'Jogo Bits Ponteiras Cromo Vanádio 7 Peças Nove54', 'O jogo de bits e ponteiras 7 peças Nove54 é indicado para fixar e soltar parafusos em geral, sendo ideal para uso doméstico, manutenção e serviços mecânicos. Versátil e prático, acompanha cabo extensor que facilita o acesso em locais de difícil alcance. Produzido em aço cromo vanádio, oferece maior resistência e durabilidade. Possui acabamento cromado que aumenta a proteção contra oxidação e corrosão. As ponteiras têm comprimento de 25 mm e encaixe sextavado 1/4" (6,35 mm), compatíveis com suportes e ferramentas padrão. O conjunto inclui bits fenda, SL, phillips e torx, atendendo diferentes tipos de parafusos. Características: Marca: Nove54 Modelo: 3599000710 Material: Aço cromo vanádio Acabamento: Cromado Comprimento dos bits: 25 mm Encaixe: Sextavado 1/4" (6,35 mm) Quantidade de peças: 7 Benefícios: Conjunto versátil para diversos tipos de parafusos Material resistente com maior durabilidade Acabamento cromado contra oxidação Acompanha cabo extensor para melhor alcance Conteúdo da embalagem: 1 Cabo extensor 1 Bits fenda 3/16" (4,76 mm) 1 Bits SL 9/32" (7,14 mm) 2 Bits phillips (PH1 e PH2) 2 Bits torx (T15 e T20)', 57.89, 44.39, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zvw-mn30bxp08pog75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F46058915219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894348471', 'Acquaflora 0.6 Mix Vermelho - Coloração Permanente 60g', 'Acquaflora 0.6 Mix Vermelho - Corretor de Nuances com Tratamento Profundo Garante clareamento e cobertura uniforme no processo de coloração ou descoloração. Com textura cremosa e glicerina na fórmula, promove condicionamento, brilho e maciez aos fios, preservando a saúde capilar durante a química. Conselho de Aplicação Para a aplicação, siga atentamente os passos descritos na bula do produto. A aplicação deverá ser feita em cabelos secos, não lavados e sem produtos finalizadores. Separar os cabelos em pequenas mechas e aplicar com o pincel por todo o comprimento e pontas, exceto nos 2 cm da raiz. Deixar agir por 20 minutos. Depois aplicar na raiz e deixar agir por mais 15 minutos. Enxaguar com água em abundância para a retirada dos resíduos.', 58.7, 34.9, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-824hg-mdxftlfsmtqd77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22894348471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
