INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998881597', 'Macaco Hidráulico Tipo Jacaré 2 Toneladas Portátil Deend', 'O Macaco Hidráulico Deend é a ferramenta ideal para quem busca praticidade, segurança e eficiência na hora de levantar veículos. Com capacidade de até 2 toneladas, ele é projetado para oferecer resistência e estabilidade, sendo indispensável em oficinas, borracharias e também no uso doméstico. Seu design compacto e reforçado garante fácil manuseio e transporte, além de proporcionar maior durabilidade e confiabilidade. Equipado com alça ergonômica, rodas de aço e bandeja giratória com encaixe, ele permite um trabalho seguro e rápido. Características: Marca: Deend Modelo: D001 Tipo: Macaco hidráulico tipo jacaré Capacidade máxima: 2 toneladas Altura mínima: 15 cm Altura máxima: 38 cm Comprimento total: 38 cm Altura até a alça: 18 cm Altura da bandeja: 15 cm Altura máxima elevada: 28 cm Material da estrutura: Aço reforçado Acabamento: Pintura eletrostática resistente Sistema: Bomba de óleo ampliada para maior eficiência Rodas: Em aço de alta qualidade Bandeja: Giratória com encaixe Alça: Ergonômica para transporte Benefícios: Mais segurança com sistema hidráulico de alta pressão Estrutura reforçada que garante durabilidade e resistência Fácil de transportar com alça ergonômica e tamanho compacto Praticidade no uso em carros de passeio, utilitários e pequenos comerciais Maior estabilidade com rodas de aço e bandeja giratória Conteúdo da embalagem: 1 Macaco hidráulico tipo jacaré 2T 1 Alavanca destacável', 258.46, 219.96, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Lift', 'https://cf.shopee.com.br/file/sg-11134201-824ii-mejaociryqyv08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23998881597', NULL, NULL, '2026-07-28T02:11:31.708458+00:0