INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398265361', 'Fio Multicabo Rack Som Profissional 5 Vias 2x24 Awg 15metros', 'Multicabo para ligações/interligações estéreo fabricado em liga de Cobre OFHC (Isento de Oxigênio) bitola de 0,20mm²/24 AWG, estanhado, com veias numeradas. CONSTRUÇÃO: - Condutor: Condutor em cobre estanhado - Isolamento: Isolado em Polietileno termoplástico resistente a alta temperatura e baixa retração durante a solda. - Blindagem: Fita de alumínio + fio de cobre (dreno) 0,20mm² - Cobertura: Cobertura em PVC emborrachado e flexível. COMPOSIÇÃO: - Capa preta PVC - 2 VIAS DE ÁUDIO AWG LR + MALHA - 2 VIAS 2X2,5mm ALIMENTAÇÃO - 1 VIA 0,75mm ALIMENTAÇÃO SINAL CARACTERÍSTICAS: - Gravação alfanumérica das vias a cada 5cm - Vem com sistema rip-cord que facilita a abertura da capa. - 100% Cobre Eletrolítico - Alta flexibilidade. - Liga de cobre OFHC - Condutor de áudio: 0.20mm² - Isolamento: Polietileno - Cor: Preto Disponíveis nas configurações: 5 Vias (espaguetes) Vias numeradas para identificação Cobertura de PVC emborrachado, mais flexível e resistente Veias revestidas de PE de baixa densidade Bitola: 24 AWG (0,20mm) Compatibilidades: - Meduza de Microfone e acessórios - Cabos de Áudio CONTEÚDO DA EMBALAGEM: - 15 Metros de Multicabo 05 vias Importante: - Cabo vendido por metragem - Valor referente a 15 metros - Imagens meramente ilustrativas - Garantia : 3 meses - Recomendamos que a instalação seja feita por um profissional, e não nos responsabilizamos pelo mau uso do produto.', 300.0, 300.0, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcm3pic5glq9fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388765779%2F21398265361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
