INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209908531', 'Café Solúvel Em Pó 3 Corações Extraforte Refil 40G', 'O Café Solúvel 3 Corações Extra Forte é a escolha perfeita para quem busca praticidade sem abrir mão da intensidade do sabor. Com um blend encorpado e aroma marcante, ele proporciona uma experiência única a cada gole. Ideal para quem aprecia um café forte e saboroso em qualquer momento do dia. Modo de preparo: 1. Adicione 1 a 2 colheres de sopa de café solúvel em uma xícara. 2. Despeje água quente (não fervente) e mexa bem até dissolver. 3. Para um toque especial, experimente adicionar leite. Este produto é 100% café solúvel, sem adição de conservantes ou ingredientes artificiais. Guarde em local fresco e seco para preservar o sabor e aroma.', 8.79, 6.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8258k-mqnem1q92z9d13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290582%2F58209908531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
